/* Series glossary schema v1: ko, en, abbr, def, chapters[]; optional category, related, audio, examples, stage.
   This is the source of truth for both the glossary page and prose tooltips. */
window.BOOK_GLOSSARY = {
  version: 1,
  terms: [
    {"ko":"결정 격자","en":"Crystal lattice","abbr":"","def":"원자가 3차원으로 주기적으로 배열된 점들의 집합. 격자점에 원자 묶음(기저)을 얹으면 결정 구조가 된다.","chapters":["crystal"]},
    {"ko":"단위 셀","en":"Unit cell","abbr":"","def":"평행 이동해 결정 전체를 채우는 기본 블록. 원시 단위 셀은 격자점 1개, 관용 단위 셀은 대칭이 잘 보이도록 더 크게 잡는다.","chapters":["crystal"]},
    {"ko":"다이아몬드 구조","en":"Diamond structure","abbr":"","def":"FCC 격자 두 개를 대각선 방향으로 a/4씩 어긋나게 겹친 구조. Si·Ge가 이 구조이며 관용 단위 셀에 원자 8개, 각 원자는 이웃 4개와 사면체 결합한다.","chapters":["crystal"]},
    {"ko":"섬아연광 구조","en":"Zincblende structure","abbr":"","def":"다이아몬드 구조에서 두 FCC 부격자를 서로 다른 원소(예: Ga와 As)가 차지한 구조. GaAs·InP 등 III–V 화합물 반도체에 많다.","chapters":["crystal"]},
    {"ko":"격자 상수","en":"Lattice constant","abbr":"a","def":"관용 단위 셀 한 변의 길이. Si 5.431 Å, GaAs 5.653 Å. Si 원자 밀도는 8/a³ ≈ 5.0×10²² cm⁻³.","chapters":["crystal"]},
    {"ko":"밀러 지수","en":"Miller indices","abbr":"(hkl)","def":"결정면이 세 축과 만나는 절편의 역수를 가장 작은 정수비로 나타낸 것. (hkl)은 면, [hkl]은 방향, {hkl}은 동등한 면의 묶음.","chapters":["crystal"]},
    {"ko":"역격자","en":"Reciprocal lattice","abbr":"","def":"실공간 격자의 푸리에 짝인 파수 공간 격자. 실공간 FCC의 역격자는 BCC이며, 회절 조건과 밴드 구조를 기술하는 무대다.","chapters":["crystal"]},
    {"ko":"브릴루앙 영역","en":"Brillouin zone","abbr":"BZ","def":"역격자의 원시 셀(위그너–자이츠 셀). 밴드 구조는 제1 브릴루앙 영역 안의 k만으로 모두 표현되며 Γ, X, L 등 대칭점으로 경로를 그린다.","chapters":["crystal"]},
    {"ko":"블로흐 정리","en":"Bloch theorem","abbr":"","def":"주기 퍼텐셜 속 전자의 파동함수는 ψ = u(r)e^(ik·r) 꼴(평면파 × 격자 주기 함수)이라는 정리. 결정 운동량 ħk와 밴드 개념의 출발점이다.","chapters":["crystal"]},
    {"ko":"크로니히–페니 모형","en":"Kronig–Penney model","abbr":"KP","def":"주기적 사각 우물 퍼텐셜에서 슈뢰딩거 방정식을 정확히 풀어 허용 밴드와 금지 대역이 생김을 보이는 1차원 모형.","chapters":["crystal"]},
    {"ko":"에너지 밴드","en":"Energy band","abbr":"","def":"원자들이 가까워지며 원자 준위가 N개로 갈라져 거의 연속이 된 허용 에너지 영역. 밴드 사이의 금지된 영역이 밴드갭이다.","chapters":["crystal"]},
    {"ko":"전도대 / 가전자대","en":"Conduction / valence band","abbr":"Ec / Ev","def":"0 K에서 비어 있는 가장 낮은 밴드가 전도대, 꽉 찬 가장 높은 밴드가 가전자대. 각각의 가장자리를 Ec, Ev로 쓴다.","chapters":["crystal"]},
    {"ko":"밴드갭","en":"Band gap","abbr":"Eg","def":"Ec − Ev. 300 K에서 Si 1.12 eV, Ge 0.66 eV, GaAs 1.42 eV, GaN 3.4 eV. 온도가 오르면 조금 줄어든다(바르시니 식).","chapters":["crystal"]},
    {"ko":"정공","en":"Hole","abbr":"h⁺","def":"가전자대에서 전자가 빠진 빈자리. 양전하 +q와 양의 유효 질량을 가진 입자처럼 다루면 가전자대 전체 전자의 운동을 간단히 기술할 수 있다.","chapters":["crystal"]},
    {"ko":"유효 질량","en":"Effective mass","abbr":"m*","def":"밴드 곡률로 정의한 질량 m* = ħ²/(d²E/dk²). 곡률이 클수록 가볍다. 결정 퍼텐셜의 효과를 질량 하나에 담아 뉴턴 방정식을 그대로 쓰게 해 준다.","chapters":["crystal"]},
    {"ko":"직접 밴드갭","en":"Direct band gap","abbr":"","def":"전도대 최저점과 가전자대 최고점이 같은 k(보통 Γ)에 있는 밴드 구조. 광자만으로 전이할 수 있어 발광이 효율적이다(GaAs, GaN).","chapters":["crystal"]},
    {"ko":"간접 밴드갭","en":"Indirect band gap","abbr":"","def":"전도대 최저점이 가전자대 최고점과 다른 k에 있는 구조. 전이에 포논이 운동량을 보태야 해 흡수가 약하고 발광이 비효율적이다(Si, Ge).","chapters":["crystal"]},
    {"ko":"포논","en":"Phonon","abbr":"","def":"격자 진동의 양자. 음향·광학 가지가 있으며 캐리어 산란과 간접 전이의 운동량 공급원이다. Si 광학 포논 에너지는 약 63 meV.","chapters":["crystal"]},
    {"ko":"등에너지면 (Si 골짜기)","en":"Constant-energy surface (valley)","abbr":"","def":"Si 전도대 최저점은 ⟨100⟩ 방향 6개 골짜기에 있고, 등에너지면은 m_l ≈ 0.92m₀, m_t ≈ 0.19m₀의 회전 타원체다.","chapters":["crystal"]},
    {"ko":"상태 밀도","en":"Density of states","abbr":"DOS","def":"단위 부피·단위 에너지당 허용 상태 수. 포물선 밴드에서 g_c(E) ∝ (m*)^(3/2)√(E − Ec).","chapters":["carriers"]},
    {"ko":"유효 상태 밀도","en":"Effective density of states","abbr":"Nc / Nv","def":"밴드 가장자리 한 준위에 모두 모여 있다고 볼 때의 등가 상태 수. ∝ T^(3/2). Si 300 K에서 Nc ≈ 2.9×10¹⁹, Nv ≈ 3.1×10¹⁹ cm⁻³(이 책 기준, 교재마다 다소 다름).","chapters":["carriers"]},
    {"ko":"페르미–디랙 분포","en":"Fermi–Dirac distribution","abbr":"f(E)","def":"에너지 E인 상태가 전자로 차 있을 확률 1/(1 + e^((E−EF)/kT)). E = EF에서 정확히 1/2.","chapters":["carriers"]},
    {"ko":"볼츠만 근사","en":"Boltzmann approximation","abbr":"","def":"E − EF ≫ kT(대략 3kT 이상)일 때 f ≈ e^(−(E−EF)/kT)로 근사하는 것. n = Nc e^(−(Ec−EF)/kT)를 준다. 축퇴 반도체에서는 깨진다.","chapters":["carriers"]},
    {"ko":"페르미 준위","en":"Fermi level","abbr":"EF","def":"점유 확률이 1/2인 에너지이자 전자의 전기화학 퍼텐셜. 평형에서는 소자 전체에서 평평하다.","chapters":["carriers"]},
    {"ko":"진성 페르미 준위","en":"Intrinsic Fermi level","abbr":"Ei","def":"진성 반도체의 페르미 준위. 밴드갭 중앙에서 (3/4)kT ln(m_h*/m_e*)만큼 어긋나며, n = ni e^((EF−Ei)/kT)의 기준점으로 쓴다.","chapters":["carriers"]},
    {"ko":"진성 캐리어 농도","en":"Intrinsic carrier concentration","abbr":"ni","def":"ni = √(NcNv) e^(−Eg/2kT). Si 300 K에서 이 책은 1.07×10¹⁰ cm⁻³(교재값 1.0–1.5×10¹⁰), GaAs 약 2×10⁶ cm⁻³. 온도에 지수적으로 민감하다.","chapters":["carriers"]},
    {"ko":"질량 작용 법칙","en":"Mass-action law","abbr":"np = ni²","def":"비축퇴 반도체가 열평형이면 도핑과 무관하게 np = ni². 다수 캐리어를 알면 소수 캐리어가 정해진다.","chapters":["carriers"]},
    {"ko":"도너","en":"Donor","abbr":"Nd","def":"전자를 하나 내주는 불순물(Si의 P, As, Sb). 이온화 에너지는 Si에서 약 45 meV(P)로 작아 상온에서 거의 모두 이온화된다.","chapters":["carriers"]},
    {"ko":"억셉터","en":"Acceptor","abbr":"Na","def":"전자를 하나 받아 정공을 만드는 불순물(Si의 B, Al, Ga). B의 이온화 에너지는 약 45 meV.","chapters":["carriers"]},
    {"ko":"이온화 에너지","en":"Ionization energy","abbr":"Ed, Ea","def":"도너 전자를 전도대로(또는 정공을 가전자대로) 떼어 내는 데 드는 에너지. 수소 원자 모형으로 13.6 eV × (m*/m₀)/εr²로 어림한다.","chapters":["carriers"]},
    {"ko":"동결","en":"Freeze-out","abbr":"","def":"저온에서 도너·억셉터가 캐리어를 다시 붙잡아 이온화율이 크게 떨어지는 현상. Si는 대략 100 K 이하에서 두드러진다.","chapters":["carriers"]},
    {"ko":"외인성 영역","en":"Extrinsic region","abbr":"","def":"도펀트가 완전히 이온화되고 ni ≪ N인 온도 범위. 다수 캐리어 농도가 도핑으로 고정되어 소자 동작의 기본 영역이 된다.","chapters":["carriers"]},
    {"ko":"진성 영역","en":"Intrinsic region","abbr":"","def":"고온에서 ni가 도핑을 넘어서 반도체가 진성처럼 동작하는 영역. 소자의 최고 동작 온도를 제한한다.","chapters":["carriers"]},
    {"ko":"보상","en":"Compensation","abbr":"","def":"도너와 억셉터가 함께 있어 서로 상쇄되는 것. 순 캐리어 농도는 |Nd − Na|로 정해지지만 이온화 불순물 산란은 Nd + Na에 비례한다.","chapters":["carriers"]},
    {"ko":"축퇴 반도체","en":"Degenerate semiconductor","abbr":"n⁺⁺ / p⁺⁺","def":"도핑이 Nc·Nv 수준(Si 약 10¹⁹ cm⁻³ 이상)이라 EF가 밴드 가장자리 근처나 밴드 안으로 들어간 반도체. 볼츠만 근사와 np = ni²가 깨지고 밴드갭 축소가 생긴다.","chapters":["carriers"]},
    {"ko":"전하 중성 조건","en":"Charge neutrality","abbr":"","def":"균일한 영역에서 p + Nd⁺ = n + Na⁻. 질량 작용 법칙과 함께 풀면 평형 n, p와 EF가 결정된다.","chapters":["carriers"]},
    {"ko":"밴드갭 축소","en":"Band-gap narrowing","abbr":"BGN","def":"고농도 도핑에서 불순물 밴드 형성과 다체 효과로 실효 밴드갭이 줄어드는 현상. 10¹⁹ cm⁻³ 이상에서 수십 meV에 이르며 이미터 효율을 떨어뜨린다.","chapters":["carriers"]},
    {"ko":"열 속도","en":"Thermal velocity","abbr":"v_th","def":"열에너지에 의한 무작위 운동 속도. (1/2)m*v² = (3/2)kT에서 Si 전자는 300 K에서 약 10⁷ cm/s.","chapters":["transport"]},
    {"ko":"드리프트","en":"Drift","abbr":"","def":"전기장에 의해 캐리어가 한 방향으로 흐르는 운동. J_drift = q(nμn + pμp)E.","chapters":["transport"]},
    {"ko":"이동도","en":"Mobility","abbr":"μ","def":"단위 전기장당 드리프트 속도 μ = qτ/m*(cm²/V·s). 저도핑 Si에서 전자 약 1400, 정공 약 470. 도핑과 온도가 오르면 감소한다.","chapters":["transport"]},
    {"ko":"산란","en":"Scattering","abbr":"","def":"캐리어가 포논·이온화 불순물·계면 거칠기 등과 부딪혀 운동량을 잃는 과정. 평균 자유 시간 τ가 이동도를 정한다.","chapters":["transport"]},
    {"ko":"격자 산란","en":"Lattice (phonon) scattering","abbr":"","def":"포논에 의한 산란. 온도가 오를수록 심해져 μ_L ∝ T^(−3/2) 정도로 감소한다.","chapters":["transport"]},
    {"ko":"이온화 불순물 산란","en":"Ionized impurity scattering","abbr":"","def":"이온화된 도펀트의 쿨롱 퍼텐셜에 의한 산란. 농도에 비례해 커지고, 빠른 캐리어는 덜 휘므로 μ_I ∝ T^(3/2)/N_I.","chapters":["transport"]},
    {"ko":"마티센 규칙","en":"Matthiessen's rule","abbr":"","def":"독립된 산란 기구의 산란률이 더해진다는 근사. 1/μ = 1/μ_L + 1/μ_I + …","chapters":["transport"]},
    {"ko":"속도 포화","en":"Velocity saturation","abbr":"v_sat","def":"강한 전기장에서 광학 포논 방출로 드리프트 속도가 더 늘지 않는 현상. Si 전자 v_sat ≈ 1×10⁷ cm/s, 대략 10⁴–10⁵ V/cm 이상에서 나타난다.","chapters":["transport"]},
    {"ko":"확산","en":"Diffusion","abbr":"","def":"농도 기울기 때문에 진한 곳에서 묽은 곳으로 캐리어가 퍼지는 흐름. Jn = qDn dn/dx, Jp = −qDp dp/dx.","chapters":["transport"]},
    {"ko":"확산 계수","en":"Diffusion coefficient","abbr":"D","def":"확산 흐름의 비례 계수(cm²/s). 저도핑 Si 전자 약 35, 정공 약 12 cm²/s.","chapters":["transport"]},
    {"ko":"아인슈타인 관계","en":"Einstein relation","abbr":"D/μ = kT/q","def":"비축퇴 반도체에서 D = μkT/q. 드리프트와 확산이 같은 산란 과정에서 나오기 때문에 성립하며, 300 K에서 kT/q ≈ 25.9 mV.","chapters":["transport"]},
    {"ko":"열전압","en":"Thermal voltage","abbr":"Vt = kT/q","def":"kT/q. 300 K에서 약 25.9 mV. 다이오드·MOSFET·BJT의 지수 법칙에 공통으로 나타나는 전압 단위다.","chapters":["transport"]},
    {"ko":"비저항","en":"Resistivity","abbr":"ρ","def":"ρ = 1/[q(nμn + pμp)] (Ω·cm). n형 Nd = 10¹⁶ cm⁻³ Si는 약 0.5 Ω·cm.","chapters":["transport"]},
    {"ko":"면저항","en":"Sheet resistance","abbr":"Rs (Ω/□)","def":"얇은 층의 저항 ρ/t. 정사각형 한 칸의 저항이 크기와 무관하므로 Ω/□ 단위를 쓰고, 저항 R = Rs·L/W로 계산한다.","chapters":["transport"]},
    {"ko":"4단자 탐침법","en":"Four-point probe","abbr":"4PP","def":"바깥 두 탐침으로 전류를 흘리고 안쪽 두 탐침으로 전압을 재 접촉 저항을 배제하는 측정. 얇은 막에서 Rs = (π/ln2)·V/I ≈ 4.53 V/I.","chapters":["transport"]},
    {"ko":"홀 효과","en":"Hall effect","abbr":"R_H","def":"전류에 수직한 자기장이 캐리어를 옆으로 밀어 생기는 가로 전압. 부호로 캐리어 종류를, R_H = 1/(qp) 또는 −1/(qn)으로 농도를 잰다.","chapters":["transport"]},
    {"ko":"드리프트–확산 전류식","en":"Drift–diffusion current equation","abbr":"","def":"Jn = qnμnE + qDn∇n. 평형에서는 두 항이 정확히 상쇄되며, 준페르미 준위로 쓰면 Jn = nμn∇EFn.","chapters":["transport"]},
    {"ko":"생성","en":"Generation","abbr":"G","def":"전자–정공 쌍이 만들어지는 과정. 열(포논), 빛(광자), 충돌 이온화 등이 에너지를 공급한다.","chapters":["gr"]},
    {"ko":"재결합","en":"Recombination","abbr":"R","def":"전도대 전자가 정공과 만나 쌍이 소멸하는 과정. 남는 에너지를 광자(복사), 포논(SRH), 제3 캐리어(오제)로 넘긴다.","chapters":["gr"]},
    {"ko":"복사 재결합","en":"Radiative recombination","abbr":"B","def":"밴드 간 직접 재결합하며 광자를 내는 과정. R = B(np − ni²). 직접 밴드갭(GaAs B ≈ 10⁻¹⁰ cm³/s)에서 크고 Si에서는 매우 작다.","chapters":["gr"]},
    {"ko":"SRH 재결합","en":"Shockley–Read–Hall recombination","abbr":"SRH","def":"밴드갭 안의 트랩 준위를 거쳐 단계적으로 재결합하는 과정. 트랩이 Ei 근처일 때 가장 효과적이며 Si의 주된 재결합 기구다.","chapters":["gr"]},
    {"ko":"트랩 준위","en":"Trap level","abbr":"Et","def":"결함·금속 불순물(Au, Fe 등)이 밴드갭 안에 만드는 국재 준위. 깊을수록(Ei에 가까울수록) 생성·재결합 중심으로 강하게 작용한다.","chapters":["gr"]},
    {"ko":"오제 재결합","en":"Auger recombination","abbr":"C","def":"재결합 에너지를 제3의 캐리어에게 넘겨 주는 과정. R ∝ C n²p 또는 C p²n이라 고농도 도핑·고주입에서 지배적이다.","chapters":["gr"]},
    {"ko":"소수 캐리어 수명","en":"Minority carrier lifetime","abbr":"τ","def":"저준위 주입에서 과잉 소수 캐리어가 1/e로 줄어드는 시간. Δn(t) = Δn₀e^(−t/τ). 고품질 Si에서 ms, 소자 영역에서 μs 수준.","chapters":["gr"]},
    {"ko":"저준위 주입","en":"Low-level injection","abbr":"","def":"과잉 캐리어 농도가 다수 캐리어 농도보다 훨씬 작은 조건(Δn ≪ n₀). 재결합률이 Δ/τ로 선형화된다.","chapters":["gr"]},
    {"ko":"확산 길이","en":"Diffusion length","abbr":"L = √(Dτ)","def":"소수 캐리어가 재결합하기 전에 평균적으로 확산하는 거리. D = 25 cm²/s, τ = 1 μs이면 50 μm.","chapters":["gr"]},
    {"ko":"연속 방정식","en":"Continuity equation","abbr":"","def":"∂n/∂t = (1/q)∇·Jn + Gn − Rn. 캐리어 수의 보존을 나타내며 드리프트–확산 모형의 핵심 방정식이다.","chapters":["gr"]},
    {"ko":"헤인스–쇼클리 실험","en":"Haynes–Shockley experiment","abbr":"","def":"빛 펄스로 만든 소수 캐리어 묶음이 전기장 속에서 이동·확산·감쇠하는 모습을 재는 실험. 도착 시간으로 μ, 퍼짐으로 D, 넓이 감소로 τ를 얻는다.","chapters":["gr"]},
    {"ko":"준페르미 준위","en":"Quasi-Fermi level","abbr":"EFn, EFp","def":"비평형에서 전자와 정공 각각의 농도를 n = ni e^((EFn−Ei)/kT), p = ni e^((Ei−EFp)/kT)로 표현하는 준위. 분리 EFn − EFp가 np/ni²를 정한다.","chapters":["gr"]},
    {"ko":"표면 재결합 속도","en":"Surface recombination velocity","abbr":"S","def":"표면 재결합 흐름을 과잉 캐리어 농도로 나눈 값(cm/s). 산화·패시베이션으로 줄이며, 태양 전지와 얇은 소자에서 중요하다.","chapters":["gr"]},
    {"ko":"광전도 감쇠","en":"Photoconductive decay","abbr":"PCD","def":"빛 펄스 뒤 전도도가 줄어드는 시간 상수로 소수 캐리어 수명을 재는 방법.","chapters":["gr"]},
    {"ko":"pn 접합","en":"pn junction","abbr":"","def":"p형과 n형 반도체가 맞닿은 구조. 캐리어 확산과 남은 이온 전하가 만든 전기장이 평형을 이룬다.","chapters":["pn"]},
    {"ko":"내부 전위","en":"Built-in potential","abbr":"Vbi","def":"평형 pn 접합 양쪽의 정전 전위 차. Vbi = (kT/q) ln(NaNd/ni²). Si Na = 10¹⁷, Nd = 10¹⁶ cm⁻³에서 약 0.77 V.","chapters":["pn"]},
    {"ko":"공핍층","en":"Depletion region","abbr":"W","def":"접합 근처에서 자유 캐리어가 거의 없고 이온화된 도펀트 전하만 남은 영역. 공간 전하 영역이라고도 한다.","chapters":["pn"]},
    {"ko":"공핍 근사","en":"Depletion approximation","abbr":"","def":"공핍층 안은 캐리어가 0, 밖은 완전 중성이라고 보고 경계를 계단처럼 자르는 근사. 푸아송 방정식을 손으로 풀 수 있게 해 준다.","chapters":["pn"]},
    {"ko":"공핍층 폭","en":"Depletion width","abbr":"W","def":"W = √[2ε(Vbi − V)(1/Na + 1/Nd)/q]. 역바이어스를 걸면 √(Vbi + VR)에 비례해 넓어진다.","chapters":["pn"]},
    {"ko":"최대 전기장","en":"Maximum electric field","abbr":"Emax","def":"계단 접합의 금속학적 경계에서 나타나는 전기장의 최댓값 qNdxn/ε = 2(Vbi − V)/W. 항복을 결정한다.","chapters":["pn"]},
    {"ko":"전하 중성 xnNd = xpNa","en":"Depletion charge balance","abbr":"","def":"공핍층 양쪽 전하가 같아야 하므로 도핑이 옅은 쪽으로 공핍층이 더 넓게 뻗는다.","chapters":["pn"]},
    {"ko":"단측 접합","en":"One-sided junction","abbr":"p⁺n / n⁺p","def":"한쪽이 훨씬 진하게 도핑된 접합. 공핍층이 거의 옅은 쪽에만 생기며 W ≈ √[2ε(Vbi − V)/(qN_옅은쪽)].","chapters":["pn"]},
    {"ko":"경사 접합","en":"Linearly graded junction","abbr":"","def":"알짜 도핑이 경계에서 선형으로 바뀌는 접합. W ∝ (Vbi − V)^(1/3), Cj ∝ (Vbi − V)^(−1/3).","chapters":["pn"]},
    {"ko":"디바이 길이","en":"Debye length","abbr":"L_D","def":"자유 캐리어가 전하 교란을 가리는 거리 √(εkT/q²N). Si N = 10¹⁶ cm⁻³에서 약 41 nm. 공핍 경계가 실제로는 몇 L_D만큼 흐려진다.","chapters":["pn"]},
    {"ko":"푸아송 방정식","en":"Poisson's equation","abbr":"","def":"d²ψ/dx² = −ρ/ε. 전하 분포에서 전위와 밴드 휨을 구한다. 소자 정전기 해석의 기본식.","chapters":["pn"]},
    {"ko":"접합 용량","en":"Junction capacitance","abbr":"Cj","def":"공핍층 전하가 전압에 따라 변해 생기는 용량 Cj = ε/W (단위 면적당). 역바이어스가 클수록 작아진다. 버랙터로 쓴다.","chapters":["pn"]},
    {"ko":"C–V 측정 (1/C² 플롯)","en":"C–V profiling","abbr":"","def":"단측 접합에서 1/C² 대 V가 직선이며 기울기 2/(qεN)로 도핑을, V축 절편으로 Vbi를 얻는다.","chapters":["pn"]},
    {"ko":"접합의 법칙","en":"Law of the junction","abbr":"","def":"바이어스 V에서 공핍층 경계의 소수 캐리어 농도가 평형값의 e^(qV/kT)배가 된다는 관계. 예: pn(xn) = pn0 e^(qV/kT).","chapters":["diode"]},
    {"ko":"소수 캐리어 주입","en":"Minority carrier injection","abbr":"","def":"순방향 바이어스에서 장벽이 낮아져 각 쪽으로 넘어간 캐리어가 소수 캐리어가 되어 확산하며 재결합하는 현상. 다이오드 전류의 근원이다.","chapters":["diode"]},
    {"ko":"쇼클리 방정식","en":"Shockley diode equation","abbr":"","def":"이상적 다이오드 전류 I = I₀(e^(qV/kT) − 1). 순방향으로 약 60 mV마다 전류가 10배 증가한다(300 K).","chapters":["diode"]},
    {"ko":"포화 전류","en":"Saturation current","abbr":"I₀ (Js)","def":"J₀ = qni²(Dp/(LpNd) + Dn/(LnNa)). ni²에 비례해 온도에 매우 민감하고 옅은 쪽 도핑이 주로 정한다.","chapters":["diode"]},
    {"ko":"이상 계수","en":"Ideality factor","abbr":"n","def":"I ∝ e^(qV/nkT)의 n. 확산 전류가 지배하면 1, 공핍층 SRH 재결합 전류가 지배하면 2에 가깝다.","chapters":["diode"]},
    {"ko":"재결합–생성 전류","en":"Recombination–generation current","abbr":"J_gr","def":"공핍층 안 트랩을 통한 재결합(순방향, ∝ e^(qV/2kT))과 생성(역방향, ∝ niW/τ) 전류. Si 다이오드의 저전류 영역과 역방향 누설을 지배한다.","chapters":["diode"]},
    {"ko":"고주입","en":"High-level injection","abbr":"","def":"주입된 소수 캐리어가 다수 캐리어 농도에 버금가는 상태. 전류가 e^(qV/2kT)로 완만해진다.","chapters":["diode"]},
    {"ko":"직렬 저항","en":"Series resistance","abbr":"Rs","def":"중성 영역·접촉의 저항. 큰 전류에서 IRs 강하로 로그 I–V 곡선이 아래로 휜다.","chapters":["diode"]},
    {"ko":"항복","en":"Breakdown","abbr":"V_BR","def":"역바이어스가 어떤 값을 넘으면 전류가 급증하는 현상. 기구로 애벌런치와 제너(터널링)가 있다.","chapters":["diode"]},
    {"ko":"충돌 이온화","en":"Impact ionization","abbr":"α_n, α_p","def":"강한 전기장에서 가속된 캐리어가 격자와 부딪혀 새 전자–정공 쌍을 만드는 과정. 이온화 계수는 전기장에 지수적으로 민감하다.","chapters":["diode"]},
    {"ko":"애벌런치 항복","en":"Avalanche breakdown","abbr":"","def":"충돌 이온화가 연쇄적으로 일어나 증배율이 발산하는 항복. 옅은 도핑·넓은 공핍층에서 일어나며 온도가 오르면 항복 전압이 커진다(양의 온도 계수).","chapters":["diode"]},
    {"ko":"제너 항복","en":"Zener breakdown","abbr":"","def":"양쪽이 진한 접합의 얇은 공핍층을 전자가 밴드 간 터널링해 생기는 항복. Si에서 대략 4Eg/q(≈ 4.5 V) 이하에서 지배하며 음의 온도 계수를 갖는다.","chapters":["diode"]},
    {"ko":"밴드 간 터널링","en":"Band-to-band tunneling","abbr":"BTBT","def":"가전자대 전자가 얇은 장벽(밴드갭)을 뚫고 전도대로 넘어가는 양자 현상. 제너 항복, GIDL, TFET의 원리다.","chapters":["diode"]},
    {"ko":"확산 용량","en":"Diffusion capacitance","abbr":"Cd","def":"순방향에서 중성 영역에 저장된 소수 캐리어 전하가 전압에 따라 변해 생기는 용량. Cd ≈ τI/(kT/q)로 전류에 비례한다.","chapters":["diode"]},
    {"ko":"저장 전하","en":"Stored charge","abbr":"Q_s","def":"순방향 다이오드의 중성 영역에 쌓인 과잉 소수 캐리어 전하. 단측 접합에서 Q ≈ Iτ.","chapters":["diode"]},
    {"ko":"역회복","en":"Reverse recovery","abbr":"t_rr","def":"순방향에서 역방향으로 갑자기 바꿔도 저장 전하가 빠질 때까지 큰 역전류가 흐르는 현상. 저장 시간 + 하강 시간으로 이뤄진다.","chapters":["diode"]},
    {"ko":"저장 시간","en":"Storage time","abbr":"t_s","def":"역회복 동안 접합 경계의 소수 캐리어가 평형값으로 돌아올 때까지 역전류가 거의 일정하게 유지되는 시간. t_s ≈ τ ln(1 + I_F/I_R).","chapters":["diode"]},
    {"ko":"짧은 다이오드","en":"Short-base diode","abbr":"","def":"중성 영역 폭이 확산 길이보다 짧은 다이오드. 소수 캐리어 분포가 직선이 되고 J₀에서 L 대신 W가 들어간다.","chapters":["diode"]},
    {"ko":"일함수","en":"Work function","abbr":"φm, φs","def":"페르미 준위의 전자를 진공 준위까지 꺼내는 데 드는 에너지. Al 약 4.1, Au 약 5.1, Pt 약 5.6 eV.","chapters":["ms"]},
    {"ko":"전자 친화도","en":"Electron affinity","abbr":"χ","def":"전도대 바닥에서 진공 준위까지의 에너지. Si 4.05 eV, GaAs 4.07 eV. 도핑과 무관한 재료 상수다.","chapters":["ms"]},
    {"ko":"쇼트키 장벽","en":"Schottky barrier","abbr":"φB","def":"금속–반도체 계면에서 금속 페르미 준위로부터 반도체 다수 캐리어 밴드 가장자리까지의 장벽 높이. 정류 접합을 만든다.","chapters":["ms"]},
    {"ko":"쇼트키–모트 규칙","en":"Schottky–Mott rule","abbr":"","def":"이상적인 계면에서 φBn = φm − χ, φBp = Eg/q − (φm − χ). 실제 Si 계면은 페르미 준위 고정 때문에 잘 따르지 않는다.","chapters":["ms"]},
    {"ko":"페르미 준위 고정","en":"Fermi-level pinning","abbr":"S","def":"계면 상태가 많아 장벽 높이가 금속 일함수에 거의 무관하게 고정되는 현상. 기울기 S = dφB/dφm이 Si에서 약 0.1–0.3.","chapters":["ms"]},
    {"ko":"금속 유도 갭 상태","en":"Metal-induced gap states","abbr":"MIGS","def":"금속 전자 파동함수가 반도체 밴드갭 안으로 감쇠하며 스며들어 생기는 계면 상태. 전하 중성 준위 쪽으로 EF를 고정하는 주요 원인이다.","chapters":["ms"]},
    {"ko":"열전자 방출","en":"Thermionic emission","abbr":"TE","def":"장벽보다 높은 에너지의 캐리어가 장벽을 넘어 흐르는 전류 기구. J = A*T² e^(−qφB/kT)(e^(qV/nkT) − 1).","chapters":["ms"]},
    {"ko":"리처드슨 상수","en":"Richardson constant","abbr":"A*","def":"열전자 방출 식의 계수 4πqm*k²/h³. 자유 전자에서 120 A/cm²K², n형 Si 약 110, GaAs 약 8.","chapters":["ms"]},
    {"ko":"영상력 장벽 저하","en":"Image-force barrier lowering","abbr":"Δφ","def":"계면 근처 전자가 금속에 유도한 영상 전하의 인력 때문에 장벽 꼭대기가 낮아지는 현상. Δφ = √(qE/4πε)로 역바이어스에서 누설이 늘어난다.","chapters":["ms"]},
    {"ko":"전계 방출","en":"Field emission","abbr":"FE","def":"도핑이 매우 높아 공핍층이 얇을 때 페르미 준위 근처 전자가 장벽을 그대로 터널링하는 기구. 저온·고도핑에서 지배적이다.","chapters":["ms"]},
    {"ko":"열–전계 방출","en":"Thermionic-field emission","abbr":"TFE","def":"열로 일부 들뜬 전자가 장벽의 얇은 윗부분을 터널링하는 중간 영역 기구. 특성 에너지 E₀₀ ∝ √N과 kT의 비로 TE·TFE·FE를 가른다.","chapters":["ms"]},
    {"ko":"오믹 접촉","en":"Ohmic contact","abbr":"","def":"전류 방향과 무관하게 작은 저항으로 선형 I–V를 보이는 접촉. Si에서는 계면을 고농도 도핑해 터널링으로 만든다.","chapters":["ms"]},
    {"ko":"접촉 비저항","en":"Specific contact resistivity","abbr":"ρc","def":"계면을 지나는 단위 면적당 저항(Ω·cm²). 전계 방출 영역에서 exp(φB/√N)에 비례해 도핑을 높일수록 급감한다. 첨단 소자는 10⁻⁹ Ω·cm² 수준을 요구한다.","chapters":["ms"]},
    {"ko":"전송선 모형","en":"Transfer length method","abbr":"TLM","def":"간격이 다른 접촉 쌍의 저항을 간격에 대해 그려 R = 2Rc + Rs·L/W에서 Rc(절편), Rs(기울기), 전송 길이 L_T를 얻는 측정법.","chapters":["ms"]},
    {"ko":"실리사이드","en":"Silicide","abbr":"TiSi₂, NiSi","def":"금속과 Si가 반응해 만든 화합물 층. 면저항과 접촉 저항을 낮추며 자기 정렬(살리사이드) 공정으로 소스·드레인·게이트에 입힌다.","chapters":["ms"]},
    {"ko":"쇼트키 다이오드","en":"Schottky diode","abbr":"SBD","def":"쇼트키 장벽을 쓴 다수 캐리어 다이오드. 소수 캐리어 저장이 없어 빠르고, pn 다이오드보다 순방향 전압이 낮지만 누설이 크다.","chapters":["ms"]},
    {"ko":"MOS 커패시터","en":"MOS capacitor","abbr":"MOS","def":"금속(게이트)–산화막–반도체의 3층 구조. 게이트 전압으로 반도체 표면의 밴드 휨과 전하를 조절하며 MOSFET의 심장이다.","chapters":["mos"]},
    {"ko":"평탄대 전압","en":"Flat-band voltage","abbr":"VFB","def":"반도체 밴드가 표면까지 평평해지는 게이트 전압. VFB = φms − Qf/Cox(산화막 전하가 계면에 있을 때).","chapters":["mos"]},
    {"ko":"일함수 차","en":"Work-function difference","abbr":"φms","def":"게이트와 반도체의 일함수 차 φm − φs. 접촉 순간 평형을 맞추느라 밴드가 휘는 정도를 정한다.","chapters":["mos"]},
    {"ko":"축적","en":"Accumulation","abbr":"","def":"p형 기판에 VG < VFB를 걸어 표면에 다수 캐리어(정공)가 몰린 상태. 용량은 Cox에 가깝다.","chapters":["mos"]},
    {"ko":"공핍 (MOS)","en":"Depletion (MOS)","abbr":"","def":"VFB < VG < Vth에서 다수 캐리어가 밀려나 이온화된 억셉터만 남은 상태. Cox와 공핍 용량이 직렬로 연결된다.","chapters":["mos"]},
    {"ko":"반전","en":"Inversion","abbr":"","def":"표면 전위가 충분히 커져 표면에 소수 캐리어(p형 기판이면 전자)가 다수 캐리어보다 많아진 상태. MOSFET 채널이 된다.","chapters":["mos"]},
    {"ko":"강반전","en":"Strong inversion","abbr":"ψs = 2φF","def":"표면 전자 농도가 기판 정공 농도와 같아지는 조건 ψs = 2φF. 이후 공핍 폭은 최대 W_max에서 멈추고 게이트 전하는 반전층이 받는다.","chapters":["mos"]},
    {"ko":"표면 전위","en":"Surface potential","abbr":"ψs","def":"반도체 표면과 중성 기판 사이의 전위 차(밴드 휨/q). 축적에서 음수, 공핍·반전에서 양수(p형 기준).","chapters":["mos"]},
    {"ko":"페르미 전위","en":"Fermi potential","abbr":"φF","def":"φF = (kT/q) ln(Na/ni). 중성 기판에서 Ei와 EF의 간격/q. Na = 10¹⁷ cm⁻³ Si에서 약 0.42 V.","chapters":["mos"]},
    {"ko":"문턱 전압","en":"Threshold voltage","abbr":"Vth","def":"강반전이 시작되는 게이트 전압. Vth = VFB + 2φF + √(2qεNa·2φF)/Cox.","chapters":["mos"]},
    {"ko":"바디 계수","en":"Body coefficient","abbr":"γ","def":"γ = √(2qεNa)/Cox (V^(1/2)). 공핍 전하가 문턱 전압에 미치는 영향과 바디 효과의 크기를 정한다.","chapters":["mos"]},
    {"ko":"산화막 용량","en":"Oxide capacitance","abbr":"Cox","def":"단위 면적당 εox/tox. SiO₂ 2 nm에서 약 1.73 μF/cm². 게이트의 채널 장악력을 정하는 가장 기본적인 양이다.","chapters":["mos"]},
    {"ko":"저주파 / 고주파 C–V","en":"Low- / high-frequency C–V","abbr":"LF / HF C–V","def":"저주파에서는 반전층 전하가 신호를 따라가 강반전 용량이 Cox로 회복되고, 고주파에서는 따라가지 못해 최소값 C_min에 머문다.","chapters":["mos"]},
    {"ko":"깊은 공핍","en":"Deep depletion","abbr":"","def":"게이트 전압을 빠르게 쓸어 반전층이 생길 시간이 없을 때 공핍층이 W_max를 넘어 계속 넓어지는 비평형 상태. 용량이 C_min 아래로 떨어진다.","chapters":["mos"]},
    {"ko":"고정 산화막 전하","en":"Fixed oxide charge","abbr":"Qf","def":"Si/SiO₂ 계면 근처 산화막 안의 움직이지 않는 양전하(보통 10¹⁰–10¹¹ q/cm²). C–V를 평행 이동시킨다(ΔVFB = −Qf/Cox).","chapters":["mos"]},
    {"ko":"가동 이온","en":"Mobile ionic charge","abbr":"Qm","def":"산화막 안을 움직이는 Na⁺·K⁺ 등의 이온. 바이어스–온도 스트레스(BTS)로 C–V가 이동하는 것으로 검출한다.","chapters":["mos"]},
    {"ko":"계면 트랩","en":"Interface traps","abbr":"Qit","def":"Si/SiO₂ 계면 댕글링 본드가 만든 밴드갭 내 준위. 표면 전위에 따라 전하가 바뀌어 C–V를 늘어뜨리고 SS를 키운다. 수소 어닐로 줄인다.","chapters":["mos"]},
    {"ko":"계면 트랩 밀도","en":"Interface trap density","abbr":"Dit","def":"단위 면적·단위 에너지당 계면 트랩 수(cm⁻²eV⁻¹). 좋은 (100) Si/SiO₂는 10¹⁰ 수준. 고·저주파 C–V 비교나 컨덕턴스법으로 잰다.","chapters":["mos"]},
    {"ko":"등가 산화막 두께","en":"Equivalent oxide thickness","abbr":"EOT","def":"같은 Cox를 내는 SiO₂ 두께 t·(3.9/k). HfO₂(k ≈ 20) 4 nm의 EOT는 약 0.78 nm.","chapters":["mos"]},
    {"ko":"High-k 절연막","en":"High-k dielectric","abbr":"HfO₂","def":"유전율이 SiO₂(3.9)보다 큰 게이트 절연막. 물리 두께를 두껍게 유지해 터널링 누설을 줄이면서 EOT를 낮춘다.","chapters":["mos"]},
    {"ko":"폴리 공핍","en":"Poly-Si gate depletion","abbr":"","def":"도핑된 폴리실리콘 게이트 쪽에도 얇은 공핍층이 생겨 실효 산화막이 두꺼워지는 현상. 금속 게이트 도입의 이유 중 하나.","chapters":["mos"]},
    {"ko":"게이트 누설","en":"Gate leakage","abbr":"Ig","def":"얇은 게이트 절연막을 지나는 터널링 전류. SiO₂가 약 2 nm 아래로 얇아지면 직접 터널링으로 두께 1 Å마다 수 배씩 급증한다.","chapters":["mos"]},
    {"ko":"파울러–노드하임 터널링","en":"Fowler–Nordheim tunneling","abbr":"FN","def":"강한 전기장으로 산화막 장벽이 삼각형이 되어 전자가 그 일부만 뚫고 지나가는 터널링. J ∝ E² e^(−B/E). 플래시 메모리 쓰기·지우기에 쓴다.","chapters":["mos"]},
    {"ko":"MOSFET","en":"Metal-oxide-semiconductor field-effect transistor","abbr":"MOSFET","def":"게이트 전압으로 소스–드레인 사이 반전 채널의 전하를 조절해 전류를 켜고 끄는 4단자 트랜지스터.","chapters":["mosfet"]},
    {"ko":"점진 채널 근사","en":"Gradual channel approximation","abbr":"GCA","def":"채널 방향 전기장의 변화가 수직 방향보다 훨씬 완만하다고 보고 각 위치를 1차원 MOS로 다루는 근사. 긴 채널 I–V 식의 기초.","chapters":["mosfet"]},
    {"ko":"선형 영역","en":"Linear (triode) region","abbr":"","def":"VDS가 작아 채널이 소스에서 드레인까지 이어진 영역. ID = μnCox(W/L)[(VGS − Vth)VDS − VDS²/2].","chapters":["mosfet"]},
    {"ko":"포화 영역","en":"Saturation region","abbr":"","def":"VDS ≥ VGS − Vth에서 드레인 쪽 채널이 핀치오프되어 전류가 거의 일정한 영역. 긴 채널에서 ID = (μnCox/2)(W/L)(VGS − Vth)².","chapters":["mosfet"]},
    {"ko":"핀치오프","en":"Pinch-off","abbr":"","def":"드레인 쪽 반전층 전하가 0이 되는 현상. 그 너머의 짧은 공핍 구간은 전기장이 강해 전자를 드레인으로 쓸어 보낸다.","chapters":["mosfet"]},
    {"ko":"포화 드레인 전압","en":"Saturation drain voltage","abbr":"VDsat","def":"포화가 시작되는 VDS. 긴 채널에서 VGS − Vth(바디 효과까지 넣으면 (VGS − Vth)/m), 짧은 채널에서는 속도 포화 때문에 더 작다.","chapters":["mosfet"]},
    {"ko":"문턱 이하 기울기","en":"Subthreshold swing","abbr":"SS","def":"문턱 아래에서 드레인 전류를 10배 바꾸는 데 필요한 게이트 전압. SS = n(kT/q)ln10 ≈ 60·n mV/dec(300 K), n = 1 + Cdep/Cox.","chapters":["mosfet"]},
    {"ko":"문턱 이하 전류","en":"Subthreshold current","abbr":"","def":"Vth 아래에서 확산으로 흐르는 약반전 전류. ID ∝ e^(q(VGS−Vth)/nkT)로 게이트 전압에 지수적이다.","chapters":["mosfet"]},
    {"ko":"바디 효과","en":"Body effect","abbr":"","def":"소스–기판 역바이어스 VSB가 공핍 전하를 늘려 Vth가 올라가는 현상. ΔVth = γ(√(2φF + VSB) − √(2φF)).","chapters":["mosfet"]},
    {"ko":"채널 길이 변조","en":"Channel-length modulation","abbr":"CLM, λ","def":"포화 영역에서 VDS가 커지면 핀치오프점이 소스 쪽으로 이동해 실효 채널이 짧아지고 ID가 조금씩 늘어나는 현상. ID ∝ (1 + λVDS).","chapters":["mosfet"]},
    {"ko":"이동도 저하","en":"Mobility degradation","abbr":"θ","def":"게이트 수직 전기장이 커질수록 계면 거칠기·포논 산란이 늘어 반전층 이동도가 감소하는 현상. μ_eff = μ₀/(1 + θ(VGS − Vth)).","chapters":["mosfet"]},
    {"ko":"트랜스컨덕턴스","en":"Transconductance","abbr":"gm","def":"gm = ∂ID/∂VGS. 긴 채널 포화에서 gm = 2ID/(VGS − Vth) = √(2μCox(W/L)ID).","chapters":["mosfet"]},
    {"ko":"출력 저항","en":"Output resistance","abbr":"ro","def":"ro = ∂VDS/∂ID ≈ 1/(λID). 고유 이득 gm·ro를 정한다.","chapters":["mosfet"]},
    {"ko":"CMOS","en":"Complementary MOS","abbr":"CMOS","def":"nMOS와 pMOS를 짝지어 한쪽만 켜지게 만든 회로 방식. 정적 상태에서 전원–접지 경로가 끊겨 대기 전력이 매우 작다.","chapters":["mosfet"]},
    {"ko":"CMOS 인버터","en":"CMOS inverter","abbr":"","def":"pMOS(위)와 nMOS(아래)를 직렬로 잇고 게이트를 묶은 가장 기본적인 논리 게이트. 출력은 입력의 반전이다.","chapters":["mosfet"]},
    {"ko":"전압 전달 특성","en":"Voltage transfer characteristic","abbr":"VTC","def":"인버터 입력 전압에 대한 출력 전압 곡선. 기울기가 −1인 두 점에서 잡음 여유 NM_H, NM_L을 정한다.","chapters":["mosfet"]},
    {"ko":"스위칭 문턱","en":"Switching threshold","abbr":"VM","def":"VTC에서 Vout = Vin인 점. nMOS와 pMOS의 강도가 같으면 VDD/2이며, pMOS 폭을 정공 이동도 차만큼 키워 맞춘다.","chapters":["mosfet"]},
    {"ko":"동적 전력","en":"Dynamic power","abbr":"P = αCV²f","def":"부하 용량을 충·방전하며 소모하는 전력 αC·VDD²·f. 전원 전압의 제곱에 비례해 전압 낮추기가 가장 효과적이다.","chapters":["mosfet"]},
    {"ko":"데너드 스케일링","en":"Dennard scaling","abbr":"","def":"치수·전압을 1/κ, 도핑을 κ배로 줄이면 전기장이 일정하고 지연 1/κ, 회로당 전력 1/κ², 전력 밀도 일정이 된다는 1974년 규칙. 2005년경 전압 축소가 멈추며 깨졌다.","chapters":["scaling"]},
    {"ko":"무어의 법칙","en":"Moore's law","abbr":"","def":"칩당 트랜지스터 수가 약 2년마다 두 배가 된다는 경험 법칙(1965년, 1975년 수정).","chapters":["scaling"]},
    {"ko":"단채널 효과","en":"Short-channel effect","abbr":"SCE","def":"채널이 짧아져 소스·드레인 공핍층이 채널 전하를 나눠 갖고 게이트의 장악력이 약해지는 현상의 총칭. Vth 롤오프, DIBL, SS 악화가 대표적이다.","chapters":["scaling"]},
    {"ko":"Vth 롤오프","en":"Threshold voltage roll-off","abbr":"","def":"채널 길이가 줄수록 문턱 전압이 낮아지는 현상. 소스·드레인이 장벽 일부를 대신 받쳐 주기 때문이며 대략 e^(−L/2λ)로 커진다.","chapters":["scaling"]},
    {"ko":"드레인 유도 장벽 저하","en":"Drain-induced barrier lowering","abbr":"DIBL","def":"드레인 전압이 소스 쪽 전위 장벽까지 낮춰 Vth가 감소하는 현상. ΔVth/ΔVDS(mV/V)로 표시하며 잘 만든 소자는 수십 mV/V.","chapters":["scaling"]},
    {"ko":"자연 길이","en":"Natural length","abbr":"λ","def":"채널 전위의 2D 교란이 감쇠하는 특성 길이. 단일 게이트 λ ≈ √((εsi/εox)·tsi·tox). 게이트로 둘러쌀수록 작아지며 L > 5–10λ이면 단채널 효과가 작다.","chapters":["scaling"]},
    {"ko":"속도 과도 현상","en":"Velocity overshoot","abbr":"","def":"전기장이 급변하는 짧은 채널에서 캐리어가 에너지 이완보다 빨리 가속되어 잠시 v_sat을 넘는 현상.","chapters":["scaling"]},
    {"ko":"탄도 수송","en":"Ballistic transport","abbr":"","def":"채널이 평균 자유 경로보다 짧아 캐리어가 거의 산란 없이 지나가는 수송. 전류는 소스 주입 속도와 후방 산란 계수로 정해진다.","chapters":["scaling"]},
    {"ko":"게이트 유도 드레인 누설","en":"Gate-induced drain leakage","abbr":"GIDL","def":"게이트–드레인 겹침 영역의 강한 전기장이 밴드 간 터널링을 일으켜 생기는 누설. 음의 VGS·큰 VDG에서 커진다.","chapters":["scaling"]},
    {"ko":"누설 전류","en":"Leakage current","abbr":"Ioff","def":"꺼진 트랜지스터에 흐르는 전류. 문턱 이하 전류, GIDL, 게이트 터널링, 접합 누설이 더해진다. Vth를 SS만큼 낮출 때마다 Ioff는 10배.","chapters":["scaling"]},
    {"ko":"FinFET","en":"Fin field-effect transistor","abbr":"FinFET","def":"세운 실리콘 핀의 양옆과 윗면을 게이트가 감싸는 다중 게이트 트랜지스터. 22 nm(2011년)부터 양산되었고 핀 폭이 자연 길이를 줄인다.","chapters":["scaling"]},
    {"ko":"게이트 올 어라운드","en":"Gate-all-around","abbr":"GAA","def":"게이트가 채널 네 면을 모두 감싸는 구조. 정전기 제어가 가장 강해 자연 길이가 가장 짧다. 3 nm(2022년)부터 양산.","chapters":["scaling"]},
    {"ko":"나노시트","en":"Nanosheet","abbr":"NS","def":"얇은 Si 판을 여러 장 쌓고 게이트로 감싼 GAA 트랜지스터. 시트 폭을 바꿔 구동 전류를 연속적으로 조절할 수 있다.","chapters":["scaling"]},
    {"ko":"CFET","en":"Complementary FET","abbr":"CFET","def":"nMOS와 pMOS를 위아래로 쌓은 차세대 구조. 셀 면적을 크게 줄일 수 있어 연구가 활발하다.","chapters":["scaling"]},
    {"ko":"터널 FET","en":"Tunnel FET","abbr":"TFET","def":"소스–채널 사이 밴드 간 터널링을 게이트로 켜고 끄는 트랜지스터. 볼츠만 꼬리를 쓰지 않아 SS < 60 mV/dec가 가능하지만 온 전류가 작다.","chapters":["scaling"]},
    {"ko":"음의 커패시턴스 FET","en":"Negative-capacitance FET","abbr":"NCFET","def":"게이트 스택에 강유전체를 넣어 음의 커패시턴스로 표면 전위를 증폭(n < 1)하려는 트랜지스터. SS < 60 mV/dec를 노린다.","chapters":["scaling"]},
    {"ko":"급경사 스위치","en":"Steep-slope device","abbr":"","def":"300 K에서 SS < 60 mV/dec를 내는 소자의 총칭(TFET, NCFET, 충돌 이온화 MOS, NEMS 등). 낮은 전압에서 높은 온/오프 비를 노린다.","chapters":["scaling"]},
    {"ko":"볼츠만 한계","en":"Boltzmann tyranny","abbr":"60 mV/dec","def":"열적으로 장벽을 넘는 전류는 e^(qV/kT)보다 가파를 수 없어 SS ≥ (kT/q)ln10 ≈ 60 mV/dec(300 K)라는 한계. 전원 전압 축소를 가로막는다.","chapters":["scaling"]},
    {"ko":"설계–공정 공동 최적화","en":"Design-technology co-optimization","abbr":"DTCO","def":"소자·공정·셀 레이아웃·회로를 함께 최적화해 면적·성능·전력을 개선하는 방식. 피치 축소가 어려워진 뒤 미세화의 주된 수단이다.","chapters":["scaling"]},
    {"ko":"변형 실리콘","en":"Strained silicon","abbr":"","def":"SiGe 소스·드레인이나 응력막으로 채널에 변형을 줘 밴드 구조를 바꾸고 이동도를 높이는 기술. 90 nm 세대(2003년)부터 쓰였다.","chapters":["scaling"]},
    {"ko":"바이폴라 접합 트랜지스터","en":"Bipolar junction transistor","abbr":"BJT","def":"이미터–베이스–컬렉터 두 pn 접합을 붙인 트랜지스터. 이미터가 베이스로 주입한 소수 캐리어가 얇은 베이스를 건너 컬렉터로 모인다.","chapters":["bjt"]},
    {"ko":"이미터 / 베이스 / 컬렉터","en":"Emitter / base / collector","abbr":"E / B / C","def":"이미터는 가장 진하게 도핑해 캐리어를 주입하고, 베이스는 얇고 중간 도핑, 컬렉터는 옅게 도핑해 높은 전압을 견딘다.","chapters":["bjt"]},
    {"ko":"순방향 활성 영역","en":"Forward active mode","abbr":"","def":"E–B 접합 순방향, C–B 접합 역방향인 증폭 영역. IC ≈ IS e^(qVBE/kT).","chapters":["bjt"]},
    {"ko":"포화 (BJT)","en":"Saturation (BJT)","abbr":"","def":"두 접합이 모두 순방향인 영역. VCE가 약 0.1–0.2 V로 작아지고 베이스에 과잉 전하가 쌓여 스위칭이 느려진다.","chapters":["bjt"]},
    {"ko":"주입 효율","en":"Emitter injection efficiency","abbr":"γ","def":"이미터 전류 중 베이스로 주입된 다수 캐리어(npn이면 전자) 성분의 비율. γ ≈ 1/(1 + (NB DE WB)/(NE DB WE)).","chapters":["bjt"]},
    {"ko":"베이스 수송 계수","en":"Base transport factor","abbr":"α_T","def":"베이스로 주입된 캐리어가 재결합하지 않고 컬렉터에 도달하는 비율. α_T ≈ 1 − WB²/(2LB²).","chapters":["bjt"]},
    {"ko":"공통 베이스 전류 이득","en":"Common-base current gain","abbr":"α","def":"α = IC/IE = γ·α_T(·M). 1에 가깝지만 1보다 조금 작다.","chapters":["bjt"]},
    {"ko":"공통 이미터 전류 이득","en":"Common-emitter current gain","abbr":"β (h_FE)","def":"β = IC/IB = α/(1 − α). α = 0.99면 β = 99. 보통 50–300.","chapters":["bjt"]},
    {"ko":"거멜 플롯","en":"Gummel plot","abbr":"","def":"log IC와 log IB를 VBE에 대해 함께 그린 그래프. 같은 로그 밑에서 두 곡선의 수직 간격은 log β이며 저전류 재결합, 고주입, 직렬 저항 영역을 한눈에 본다.","chapters":["bjt"]},
    {"ko":"거멜 수","en":"Gummel number","abbr":"Q_B","def":"베이스 도핑을 폭에 대해 적분한 값 ∫NB dx. IS ∝ 1/Q_B이고 주입 효율과 펀치스루를 좌우한다.","chapters":["bjt"]},
    {"ko":"얼리 효과","en":"Early effect","abbr":"","def":"VCE가 커지면 C–B 공핍층이 넓어져 중성 베이스 폭이 줄고 IC가 늘어나는 현상(베이스 폭 변조).","chapters":["bjt"]},
    {"ko":"얼리 전압","en":"Early voltage","abbr":"VA","def":"고정 VBE 또는 IB의 순방향 활성 영역 IC–VCE 직선을 연장해 VCE축과 만나는 점의 크기. 출력 저항 ro ≈ VA/IC.","chapters":["bjt"]},
    {"ko":"커크 효과","en":"Kirk effect","abbr":"","def":"큰 전류에서 컬렉터로 들어간 캐리어 전하가 컬렉터 도핑을 상쇄해 실효 베이스가 컬렉터 쪽으로 넓어지는 현상(베이스 밀려남). β와 fT가 떨어진다.","chapters":["bjt"]},
    {"ko":"에버스–몰 모형","en":"Ebers–Moll model","abbr":"","def":"두 개의 다이오드와 두 개의 종속 전류원으로 BJT의 모든 동작 영역을 기술하는 대신호 모형. 상반 관계 αF·IES = αR·ICS.","chapters":["bjt"]},
    {"ko":"차단 주파수","en":"Cutoff (transition) frequency","abbr":"fT","def":"공통 이미터 단락 전류 이득이 1로 떨어지는 주파수. fT = 1/(2πτ_EC), 베이스 통과 시간 WB²/(2DB) 등 지연의 합이 정한다.","chapters":["bjt"]},
    {"ko":"베이스 통과 시간","en":"Base transit time","abbr":"τ_B","def":"주입된 캐리어가 베이스를 건너는 데 걸리는 시간 WB²/(2DB). 베이스를 얇게 할수록 제곱으로 빨라진다.","chapters":["bjt"]},
    {"ko":"이종 접합 바이폴라 트랜지스터","en":"Heterojunction bipolar transistor","abbr":"HBT","def":"이미터에 밴드갭이 더 넓은 재료를 써 정공 역주입을 e^(ΔEg/kT)만큼 억제한 BJT. 베이스를 진하게 도핑해도 β가 높아 고속에 유리하다.","chapters":["bjt"]},
    {"ko":"SiGe HBT","en":"SiGe heterojunction bipolar transistor","abbr":"SiGe","def":"베이스에 SiGe를 넣어 밴드갭을 줄이고 Ge 농도 경사로 내부 전기장을 만든 HBT. fT·fmax 수백 GHz로 RF·밀리미터파 회로에 쓴다.","chapters":["bjt"]},
    {"ko":"펀치스루","en":"Punch-through","abbr":"","def":"C–B 공핍층이 베이스 전체를 뚫고 E–B 공핍층과 만나 전류가 제어 없이 흐르는 항복 기구.","chapters":["bjt"]},
    {"ko":"흡수 계수","en":"Absorption coefficient","abbr":"α","def":"빛 세기가 I = I₀e^(−αx)로 줄어들 때의 계수(cm⁻¹). 직접 밴드갭은 갭 위에서 10⁴ cm⁻¹ 이상으로 급히 오르고, Si는 간접이라 가시광 끝에서 완만하다.","chapters":["opto"]},
    {"ko":"침투 깊이","en":"Penetration depth","abbr":"1/α","def":"빛이 1/e(약 37 %)로 줄어드는 깊이. Si에서 파란빛(450 nm)은 약 0.4 μm, 근적외선(900 nm)은 약 30 μm.","chapters":["opto"]},
    {"ko":"광자 에너지와 파장","en":"Photon energy–wavelength","abbr":"λ = 1240/E","def":"λ(nm) ≈ 1240/E(eV). Si 1.12 eV → 약 1.1 μm, GaAs 1.42 eV → 약 870 nm가 흡수·발광의 경계다.","chapters":["opto"]},
    {"ko":"광 생성","en":"Photogeneration","abbr":"G(x)","def":"흡수된 광자가 전자–정공 쌍을 만드는 과정. G(x) = αΦ₀e^(−αx)(Φ₀: 흡수된 광자 선속).","chapters":["opto"]},
    {"ko":"양자 효율","en":"Quantum efficiency","abbr":"QE","def":"입사 광자 하나당 모인 전자 수(검출기) 또는 주입 전자 하나당 나온 광자 수(발광 소자).","chapters":["opto"]},
    {"ko":"응답도","en":"Responsivity","abbr":"R (A/W)","def":"입사 광 전력당 광전류 R = ηqλ/(hc) ≈ ηλ(nm)/1240 A/W. η = 0.8, 850 nm에서 약 0.55 A/W.","chapters":["opto"]},
    {"ko":"포토다이오드","en":"Photodiode","abbr":"PD","def":"역바이어스(또는 0 V) pn 접합에서 광 생성 캐리어를 공핍층 전기장으로 분리해 전류로 바꾸는 검출기.","chapters":["opto"]},
    {"ko":"pin 포토다이오드","en":"p-i-n photodiode","abbr":"pin","def":"p와 n 사이에 넓은 진성층을 둔 포토다이오드. 흡수 영역이 넓어 효율이 높고, 용량이 작아 빠르다.","chapters":["opto"]},
    {"ko":"애벌런치 포토다이오드","en":"Avalanche photodiode","abbr":"APD","def":"항복 근처 역바이어스로 광 생성 캐리어를 충돌 이온화로 증배(M = 10–100)하는 검출기. 증배 잡음이 따른다. 항복 이상에서 쓰면 단일 광자 검출(SPAD).","chapters":["opto"]},
    {"ko":"태양 전지","en":"Solar cell","abbr":"PV","def":"빛으로 만든 전류를 외부 부하에 전력으로 공급하는 pn 접합. I = I₀(e^(qV/nkT) − 1) − I_L로 I–V 곡선이 4사분면으로 내려간다.","chapters":["opto"]},
    {"ko":"개방 전압","en":"Open-circuit voltage","abbr":"Voc","def":"전류가 0일 때의 전압 (nkT/q)ln(I_L/I₀ + 1). I₀가 작을수록(재결합이 적을수록) 크다. 결정질 Si 셀은 약 0.7 V.","chapters":["opto"]},
    {"ko":"단락 전류","en":"Short-circuit current","abbr":"Isc (Jsc)","def":"전압이 0일 때의 광전류. 흡수와 수집 효율이 정하며, 좋은 Si 셀은 약 40 mA/cm²(AM1.5G).","chapters":["opto"]},
    {"ko":"충진율","en":"Fill factor","abbr":"FF","def":"최대 전력점 전력 Pmax를 Voc·Isc로 나눈 값. 좋은 Si 셀은 0.8 이상. 효율 η = Voc·Jsc·FF/P_in.","chapters":["opto"]},
    {"ko":"쇼클리–퀘이서 한계","en":"Shockley–Queisser limit","abbr":"SQ","def":"단일 접합 태양 전지의 상세 균형 효율 한계. AM1.5G에서 Eg ≈ 1.34 eV일 때 약 33.7 %, Si(1.12 eV)는 약 32–33 %.","chapters":["opto"]},
    {"ko":"발광 다이오드","en":"Light-emitting diode","abbr":"LED","def":"순방향 pn 접합에 주입된 전자와 정공의 복사 재결합으로 빛을 내는 소자. 직접 밴드갭 재료(InGaN, AlGaInP 등)를 쓴다.","chapters":["opto"]},
    {"ko":"내부 양자 효율","en":"Internal quantum efficiency","abbr":"IQE","def":"활성층 재결합 중 복사 재결합의 비율 R_rad/(R_rad + R_SRH + R_Auger).","chapters":["opto"]},
    {"ko":"외부 양자 효율","en":"External quantum efficiency","abbr":"EQE","def":"주입 전자당 소자 밖으로 나온 광자 수. EQE = 주입 효율 × IQE × 추출 효율.","chapters":["opto"]},
    {"ko":"추출 효율","en":"Light extraction efficiency","abbr":"η_ext","def":"만들어진 광자가 소자 밖으로 빠져나오는 비율. 굴절률이 큰 반도체에서는 전반사 때문에 평평한 한 면으로 몇 %에 불과해 표면 요철·칩 성형으로 높인다.","chapters":["opto"]},
    {"ko":"탈출 원뿔","en":"Escape cone","abbr":"θc","def":"전반사되지 않고 빠져나갈 수 있는 임계각 θc = arcsin(n₂/n₁) 안의 원뿔. n = 3.5에서 공기로 θc ≈ 16.6°, 한 면의 탈출 비율 약 2 %.","chapters":["opto"]},
    {"ko":"효율 저하","en":"Efficiency droop","abbr":"droop","def":"LED 전류 밀도가 커질수록 EQE가 떨어지는 현상. 오제 재결합, 캐리어 누설 등이 원인으로 꼽힌다.","chapters":["opto"]},
    {"ko":"유도 방출","en":"Stimulated emission","abbr":"","def":"들어온 광자가 들뜬 전자를 재결합시켜 같은 위상·방향·에너지의 광자를 하나 더 만드는 과정. 레이저 증폭의 원리.","chapters":["opto"]},
    {"ko":"밀도 반전","en":"Population inversion","abbr":"","def":"유도 방출이 흡수보다 우세해지는 조건. 반도체에서는 EFn − EFp > ħω(버나드–듀라포 조건)일 때 이득이 생긴다.","chapters":["opto"]},
    {"ko":"레이저 문턱","en":"Lasing threshold","abbr":"I_th","def":"광 이득이 공진기 손실(내부 손실 + 거울 손실)과 같아지는 전류. 그 이상에서 출력이 급증하고 스펙트럼이 좁아진다.","chapters":["opto"]},
    {"ko":"이중 이종 구조","en":"Double heterostructure","abbr":"DH","def":"얇은 좁은 밴드갭 활성층을 넓은 밴드갭 층으로 감싼 구조. 캐리어와 빛을 함께 가둬 레이저 문턱을 크게 낮췄다.","chapters":["opto"]},
    {"ko":"드리프트–확산 모형","en":"Drift–diffusion model","abbr":"DD","def":"푸아송 방정식과 전자·정공 연속 방정식(드리프트+확산 전류식)을 연립한 반고전적 소자 모형. 대부분의 TCAD 소자 시뮬레이션의 기본.","chapters":["lab"]},
    {"ko":"샤페터–거멜 이산화","en":"Scharfetter–Gummel discretization","abbr":"SG","def":"격자 구간에서 전위가 선형이라 보고 전류식을 정확히 적분해 베르누이 함수로 쓴 이산화. 격자 간 전위 차가 커도 진동 없이 안정하다.","chapters":["lab"]},
    {"ko":"거멜 반복법","en":"Gummel iteration","abbr":"","def":"푸아송과 두 연속 방정식을 번갈아 따로 푸는 디커플 반복법. 저전류에서 안정하지만 강한 결합(고주입)에서는 느려 뉴턴법을 쓴다.","chapters":["lab"]},
    {"ko":"뉴턴법 (결합 해법)","en":"Newton (coupled) method","abbr":"","def":"세 방정식을 한꺼번에 선형화해 야코비안으로 푸는 방법. 초깃값이 좋으면 2차 수렴한다.","chapters":["lab"]},
    {"ko":"TCAD","en":"Technology CAD","abbr":"TCAD","def":"공정과 소자 특성을 수치로 모의하는 소프트웨어. 이 책의 1D 솔버는 그 교육용 축소판이다.","chapters":["lab"]},
    {"ko":"오믹 경계 조건","en":"Ohmic boundary condition","abbr":"","def":"이상적 오믹 접촉에서 전하 중성(n − p = Nd − Na)과 열평형(np = ni²)을 만족하도록 n, p를 고정하고 전위를 Vbi 성분 + 인가 전압으로 두는 경계 조건.","chapters":["lab"]},
    {"ko":"격자 (메시)","en":"Mesh","abbr":"","def":"방정식을 푸는 이산 점들. 공핍층처럼 전위가 급변하는 곳은 디바이 길이보다 촘촘해야 정확하다.","chapters":["lab"]},
    {"ko":"이종 접합","en":"Heterojunction","abbr":"","def":"밴드갭이나 전자 친화도가 서로 다른 두 반도체를 하나의 결정으로 이은 접합. 계면에서 전도대와 가전자대가 계단처럼 끊긴다.","chapters":["hetero"]},
    {"ko":"진공 준위","en":"Vacuum level","abbr":"E_vac","def":"전자가 물질을 막 벗어나 표면 바로 바깥에 정지해 있을 때의 에너지. 서로 다른 물질의 준위를 비교하는 공통 기준이며 접합을 지나며 연속이다.","chapters":["hetero"]},
    {"ko":"밴드 오프셋","en":"Band offset","abbr":"ΔEc, ΔEv","def":"이종 접합 계면에서 전도대(ΔEc)와 가전자대(ΔEv)가 끊기는 높이. 둘의 합이 밴드갭 차이 ΔEg이며 도핑과 바이어스에 무관한 재료 쌍 고유값이다.","chapters":["hetero"]},
    {"ko":"앤더슨 규칙","en":"Anderson's electron affinity rule","abbr":"","def":"두 물질의 진공 준위를 맞춰 전도대 오프셋을 ΔEc = χ₁ − χ₂로 구하는 규칙. 계면 쌍극자를 무시하므로 0.1~0.2 eV 틀릴 수 있다.","chapters":["hetero"]},
    {"ko":"60:40 규칙","en":"60:40 rule (GaAs/AlGaAs)","abbr":"","def":"GaAs/AlGaAs에서 밴드갭 차이의 약 60~65%가 전도대, 35~40%가 가전자대 오프셋이 된다는 경험칙. 초기의 85:15 값을 1980년대 중반 측정이 바로잡았다.","chapters":["hetero"]},
    {"ko":"타입 I 정렬","en":"Type-I (straddling) alignment","abbr":"","def":"한 물질의 금지대가 다른 물질의 금지대 안에 완전히 들어가는 정렬. 전자와 정공이 모두 좁은 갭 쪽에 모여 레이저·LED에 쓰인다.","chapters":["hetero"]},
    {"ko":"타입 II 정렬","en":"Type-II (staggered) alignment","abbr":"","def":"두 금지대가 어긋나게 겹치는 정렬. 전자는 한쪽, 정공은 다른 쪽에 모여 공간적으로 분리된다. 예: InP/InAlAs, 인장 변형 Si/완화 SiGe.","chapters":["hetero"]},
    {"ko":"타입 III 정렬","en":"Type-III (broken-gap) alignment","abbr":"","def":"한 물질의 전도대 바닥이 다른 물질의 가전자대 꼭대기보다 낮아 금지대가 전혀 겹치지 않는 정렬. InAs/GaSb가 대표적이다.","chapters":["hetero"]},
    {"ko":"격자 정합","en":"Lattice matching","abbr":"","def":"두 결정의 격자 상수가 거의 같아 계면에 전위 없이 이어 키울 수 있는 상태. GaAs/AlAs(차이 약 0.14%), In₀.₅₃Ga₀.₄₇As/InP가 대표적이다.","chapters":["hetero"]},
    {"ko":"스파이크와 노치","en":"Spike and notch","abbr":"","def":"이종 접합에서 밴드 휨에 오프셋 계단이 더해져 계면에 생기는 뾰족한 봉우리(스파이크)와 패인 골(노치). 스파이크는 캐리어 주입을 막고 노치에는 캐리어가 쌓인다.","chapters":["hetero"]},
    {"ko":"이형·동형 접합","en":"Anisotype / isotype heterojunction","abbr":"","def":"도핑 형이 다른 이종 접합(N-p 등)을 이형, 같은 이종 접합(N-n 등)을 동형이라 한다. 넓은 갭 쪽을 대문자로 쓰는 크뢰머 표기를 따른다.","chapters":["hetero"]},
    {"ko":"조성 경사","en":"Compositional grading","abbr":"","def":"합금 조성을 수십 nm에 걸쳐 서서히 바꿔 계단형 오프셋을 완만한 경사로 바꾸는 기법. HBT 이미터–베이스 접합의 스파이크를 없앤다.","chapters":["hetero"]},
    {"ko":"변조 도핑","en":"Modulation doping","abbr":"","def":"도너를 넓은 갭 층에만 넣고 전자는 도핑하지 않은 좁은 갭 층으로 옮겨 가게 해 전자와 이온화 도너를 공간적으로 떼어 놓는 방법. 1978년 벨 연구소에서 처음 시연되었다.","chapters":["hetero"]},
    {"ko":"스페이서층","en":"Spacer layer","abbr":"","def":"변조 도핑 구조에서 도핑층과 채널 사이에 넣는 도핑하지 않은 넓은 갭 층(수 nm~수십 nm). 원격 이온 산란을 줄이지만 옮겨 가는 전자 수도 줄인다.","chapters":["hetero"]},
    {"ko":"2차원 전자 가스","en":"Two-dimensional electron gas","abbr":"2DEG","def":"계면 우물에 갇혀 수직 운동이 양자화되고 평면 두 방향으로만 자유롭게 움직이는 전자 층. 시트 밀도 n_s(cm⁻²)로 나타낸다.","chapters":["hetero"]},
    {"ko":"고전자 이동도 트랜지스터","en":"High-electron-mobility transistor","abbr":"HEMT","def":"변조 도핑 이종 접합의 2DEG를 채널로 쓰는 FET. 쇼트키 게이트로 n_s를 조절하며 고주파·저잡음 증폭기와 GaN 전력 스위치에 쓰인다.","chapters":["hetero"]},
    {"ko":"부밴드","en":"Subband","abbr":"","def":"한 방향으로 갇힌 캐리어의 양자화된 에너지 준위 Eₙ마다 평면 방향 운동이 더해져 생기는 2차원 밴드. 부밴드마다 상수 상태 밀도를 가진다.","chapters":["hetero"]},
    {"ko":"삼각 우물","en":"Triangular quantum well","abbr":"","def":"계면 전기장이 만드는 거의 직선 기울기의 퍼텐셜 우물. 부밴드 에너지가 전기장의 2/3제곱에 비례한다(에어리 함수 해).","chapters":["hetero"]},
    {"ko":"양자 우물","en":"Quantum well","abbr":"QW","def":"좁은 갭 층을 넓은 갭 층 사이에 수 nm 두께로 끼워 캐리어를 한 방향으로 가둔 구조. 폭이 좁을수록 준위가 올라가 발광 파장이 짧아진다.","chapters":["hetero"]},
    {"ko":"2차원 상태 밀도","en":"Two-dimensional density of states","abbr":"","def":"평면 운동만 하는 캐리어의 상태 밀도 m*/(πħ²)(스핀 포함). 에너지와 무관한 상수이며 GaAs 전자는 약 2.8×10¹³ cm⁻²eV⁻¹이다. 부밴드가 쌓이면 계단형이 된다.","chapters":["hetero"]},
    {"ko":"벤대니얼–듀크 경계 조건","en":"BenDaniel–Duke boundary condition","abbr":"","def":"유효 질량이 다른 두 물질의 계면에서 파동 함수 ψ와 ψ′/m*이 연속이어야 한다는 조건. 확률 흐름을 보존한다.","chapters":["hetero"]},
    {"ko":"의사 정합 성장","en":"Pseudomorphic growth","abbr":"","def":"격자 상수가 다른 얇은 층이 기판의 평면 원자 간격을 그대로 따라 결함 없이 자라는 것. 층은 이축 변형을 받는다.","chapters":["hetero"]},
    {"ko":"임계 두께","en":"Critical thickness","abbr":"h_c","def":"의사 정합 층이 부정합 전위 없이 버틸 수 있는 최대 두께. 매슈스–블레이크슬리 식으로 구하며 Si₀.₈Ge₀.₂/Si는 약 12 nm다.","chapters":["hetero"]},
    {"ko":"부정합 전위","en":"Misfit dislocation","abbr":"","def":"임계 두께를 넘은 변형층이 풀리면서 계면에 생기는 선결함. 누설과 재결합의 원인이 된다.","chapters":["hetero"]},
    {"ko":"골짜기 분리","en":"Valley splitting","abbr":"","def":"변형으로 Si 전도대의 등가 골짜기 여섯 개(Δ6)가 에너지가 다른 무리(Δ2, Δ4)로 갈라지는 현상. 인장 변형 Si에서 전자가 가벼운 Δ2로 몰려 이동도가 오른다.","chapters":["hetero"]},
    {"ko":"전력 반도체 소자","en":"Power semiconductor device","abbr":"","def":"꺼졌을 때 수백~수천 V를 막고 켜졌을 때 큰 전류를 작은 손실로 흘리는 스위치·정류 소자. 다이오드, 전력 MOSFET, IGBT, 사이리스터, SiC·GaN 소자가 있다.","chapters":["power"]},
    {"ko":"특성 온저항","en":"Specific on-resistance","abbr":"R_on,sp","def":"켜진 상태 저항에 활성 면적을 곱한 값(Ω·cm²). 칩 크기와 무관하게 소자 기술을 비교하는 지표이며 R_on = R_on,sp/A이다.","chapters":["power"]},
    {"ko":"이온화 계수","en":"Impact ionization coefficient","abbr":"α_n, α_p","def":"캐리어가 단위 길이를 진행하며 새 전자–정공 쌍을 만드는 횟수(cm⁻¹). 처노웨스 식 α = a·exp(−b/ℰ)처럼 전기장에 지수적으로 민감하다.","chapters":["power"]},
    {"ko":"이온화 적분","en":"Ionization integral","abbr":"","def":"공핍층 전체에 걸쳐 이온화 계수를 적분한 값. 1에 도달하면 증배율 M = 1/(1−I)이 발산하며 이것이 애벌런치 항복 조건이다.","chapters":["power"]},
    {"ko":"임계 전기장","en":"Critical electric field","abbr":"ℰ_c","def":"애벌런치 항복이 일어나는 순간의 최대 전기장. Si 약 0.2~0.4 MV/cm, 4H-SiC·GaN 약 2.5~3.5 MV/cm이며 도핑에 따라 N^(1/8) 정도로 천천히 변한다.","chapters":["power"]},
    {"ko":"드리프트층","en":"Drift region","abbr":"","def":"전력 소자에서 차단 전압을 막는 옅게 도핑된 두꺼운 층. 켜진 상태에서는 전류가 지나가는 저항이 되어 BV와 온저항의 트레이드오프를 만든다.","chapters":["power"]},
    {"ko":"NPT / PT 설계","en":"Non-punch-through / punch-through design","abbr":"NPT, PT","def":"항복 시 공핍층이 드리프트층 안에서 끝나면 NPT(삼각형 전기장), n⁺층에 닿으면 PT(사다리꼴 전기장). 최적 PT는 두께 약 0.75배로 저항을 10~16% 줄인다.","chapters":["power"]},
    {"ko":"필드 스톱","en":"Field stop","abbr":"FS","def":"드리프트층과 뒷면 사이에 넣는 조금 더 진한 n층. 전기장을 잘라 PT 설계처럼 드리프트층을 얇게 만들며 IGBT의 온전압과 꼬리 전류를 함께 줄인다.","chapters":["power"]},
    {"ko":"단극 한계","en":"Unipolar limit (silicon limit)","abbr":"","def":"1차원 드리프트층이 낼 수 있는 최소 특성 온저항 R_on,sp = 4BV²/(εμℰc³). Si는 약 5.93×10⁻⁹·BV^2.5 Ω·cm²이다.","chapters":["power"]},
    {"ko":"바리가 성능 지수","en":"Baliga's figure of merit","abbr":"BFOM","def":"εμℰc³로 정의되는 단극 전력 소자 재료의 지표. 같은 BV에서 온저항에 반비례하며 SiC는 Si의 수백 배, GaN은 약 천 배다.","chapters":["power"]},
    {"ko":"접합 종단","en":"Edge termination","abbr":"","def":"칩 가장자리의 휜 접합에 전기장이 몰려 BV가 떨어지는 것을 막는 구조. 가드 링, 필드 플레이트, JTE 등으로 평면 BV의 90% 이상을 회복한다.","chapters":["power"]},
    {"ko":"DMOS","en":"Double-diffused MOS","abbr":"DMOS","def":"같은 마스크 창으로 p 바디와 n⁺ 소스를 차례로 확산시켜 깊이 차이로 짧은 채널을 만든 수직형 전력 MOSFET. 두 p 바디 사이에 JFET 영역이 생긴다.","chapters":["power"]},
    {"ko":"트렌치 MOSFET","en":"Trench MOSFET (UMOS)","abbr":"","def":"게이트를 실리콘 홈 속에 묻어 채널을 수직으로 세운 전력 MOSFET. JFET 영역이 없고 셀 피치를 1~5 µm로 줄여 저전압 온저항이 작다.","chapters":["power"]},
    {"ko":"JFET 영역","en":"JFET region","abbr":"","def":"평면 DMOS에서 이웃한 두 p 바디 사이의 좁은 n 통로. 영 바이어스 공핍층이 폭을 좁혀 저항을 만들며, 셀 피치를 줄이면 막혀 저항이 급증한다.","chapters":["power"]},
    {"ko":"슈퍼정션","en":"Superjunction","abbr":"SJ","def":"드리프트층을 전하가 같은 n·p 기둥으로 번갈아 채운 구조. 옆으로 먼저 공핍되어 수직 전기장이 평평해지므로 도핑을 높여 실리콘 한계보다 낮은 온저항을 낸다.","chapters":["power"]},
    {"ko":"IGBT","en":"Insulated-gate bipolar transistor","abbr":"IGBT","def":"전력 MOSFET의 n⁺ 기판을 p⁺로 바꿔, MOS 게이트로 넓은 베이스 pnp 트랜지스터를 구동하는 소자. 정공 주입으로 600 V 이상에서 낮은 온전압을 얻는다.","chapters":["power"]},
    {"ko":"전도도 변조","en":"Conductivity modulation","abbr":"","def":"옅게 도핑된 층에 도핑보다 훨씬 많은 전자·정공이 주입되어 저항이 크게 떨어지는 현상. pin 다이오드와 IGBT의 낮은 온전압의 원천이다.","chapters":["power"]},
    {"ko":"꼬리 전류","en":"Tail current","abbr":"","def":"IGBT를 끈 뒤 드리프트층에 남은 저장 전하가 재결합하며 흐르는 서서히 줄어드는 전류. 턴오프 손실의 주원인이며 수명을 줄이면 짧아지지만 온전압이 오른다.","chapters":["power"]},
    {"ko":"래치업","en":"Latch-up","abbr":"","def":"기생 pnpn 사이리스터의 npn과 pnp가 서로를 켜 주어(β_n·β_p > 1) 전원에서 접지로 큰 전류가 계속 흐르는 현상. 벌크 CMOS에서는 웰·기판 주입 전류가, IGBT에서는 큰 전류가 방아쇠가 되며, 전원을 끄기 전에는 풀리지 않는다.","chapters":["power","esd"]},
    {"ko":"분극 전하","en":"Polarization charge","abbr":"σ_pol","def":"우르츠광 AlGaN/GaN 계면에서 자발 분극과 압전 분극이 불연속해 생기는 고정 면전하(~10¹³ cm⁻²). 도핑 없이 2차원 전자 가스를 유도한다.","chapters":["power"]},
    {"ko":"노멀리 오프","en":"Normally-off (enhancement mode)","abbr":"","def":"게이트 전압이 0일 때 꺼져 있는 동작. 전력 스위치의 안전에 필요하며 GaN HEMT는 p-GaN 게이트, 게이트 리세스, 캐스코드로 구현한다.","chapters":["power"]},
    {"ko":"전류 붕괴","en":"Current collapse (dynamic R_on)","abbr":"","def":"고전압 스위칭 직후 표면·버퍼 트랩이 전자를 붙잡아 GaN HEMT의 켜진 상태 저항이 일시적으로 커지는 현상. 패시베이션과 필드 플레이트로 줄인다.","chapters":["power"]},
    {"ko":"이중 펄스 시험","en":"Double-pulse test","abbr":"DPT","def":"유도성 부하와 환류 다이오드로 두 번의 게이트 펄스를 가해 같은 전류에서의 턴오프·턴온 파형과 스위칭 에너지를 측정하는 표준 시험.","chapters":["power"]},
    {"ko":"밀러 평탄부","en":"Miller plateau","abbr":"V_gp","def":"스위칭 중 게이트 전류가 모두 게이트–드레인 용량 C_gd를 충방전하는 데 쓰여 v_GS가 V_th + I_L/g_fs에 머무는 구간. 이때 드레인 전압이 변한다.","chapters":["power"]},
    {"ko":"안전 동작 영역","en":"Safe operating area","abbr":"SOA","def":"소자가 파괴 없이 견디는 전압–전류 범위. 로그 축에서 온저항, 최대 전류, 열(기울기 −1), 2차 항복, 항복 전압 경계로 그린다.","chapters":["power"]},
    {"ko":"준정적 근사","en":"Quasi-static approximation","abbr":"QS","def":"소자의 전하가 그 순간의 단자 전압만으로 정해진다고 보는 가정. 신호 주기가 채널 통과 시간(L²/μV_ov 또는 L/v_sat)보다 충분히 길 때 성립하며, 이 가정 위에서 커패시턴스 C = ∂Q/∂V를 정의한다.","chapters":["rf"]},
    {"ko":"비준정적 효과","en":"Non-quasi-static effect","abbr":"NQS","def":"신호가 빨라 채널 전하가 게이트 전압을 즉시 따라가지 못해 생기는 지연과 감쇠. 채널을 분포 RC 전송선으로 보면 설명되며, 소자 모델에서는 게이트 직렬 저항 약 1/(5g_m)과 g_m 지연으로 근사한다.","chapters":["rf"]},
    {"ko":"소신호 등가 회로","en":"Small-signal equivalent circuit","abbr":"","def":"DC 동작점 근처에서 전류·전하를 1차 전개해 소자를 컨덕턴스·커패시턴스·종속 전류원으로 바꾼 선형 회로. MOSFET은 g_m, g_ds, C_gs, C_gd, R_g로 나타낸다.","chapters":["rf"]},
    {"ko":"하이브리드-π 모델","en":"Hybrid-π model","abbr":"","def":"BJT의 소신호 등가 회로. 베이스 저항 r_b, 입력 저항 r_π = β/g_m, 확산·접합 용량 C_π = g_mτ_F + C_je, B–C 용량 C_μ, 전류원 g_m·v_π, 출력 저항 r_o로 이루어진다.","chapters":["rf"]},
    {"ko":"y 파라미터","en":"Admittance parameters","abbr":"Y","def":"2단자쌍 망의 포트 전류를 포트 전압의 선형 결합으로 쓴 행렬 I = YV. 각 성분은 다른 포트를 단락하고 정의하며, 등가 회로에서 계산하기 쉽다.","chapters":["rf"]},
    {"ko":"S 파라미터","en":"Scattering parameters","abbr":"S","def":"기준 임피던스(보통 50 Ω)로 끝맺은 포트에서 들어가는 파동 a와 나오는 파동 b의 비 b = Sa. 고주파에서 단락·개방 없이 벡터 네트워크 분석기로 잴 수 있어 RF 소자 측정의 표준이다.","chapters":["rf"]},
    {"ko":"단락 전류 이득","en":"Short-circuit current gain","abbr":"h21","def":"출력을 교류 단락했을 때 출력 전류와 입력 전류의 비 h21 = y21/y11. 크기가 1이 되는 주파수가 차단 주파수 f_T이며, 높은 주파수에서 −20 dB/decade로 떨어진다.","chapters":["rf"]},
    {"ko":"메이슨 단방향 이득","en":"Mason's unilateral gain","abbr":"U","def":"입·출력을 손실 없이 정합하고 내부 귀환을 상쇄했을 때의 전력 이득. 손실 없는 가역 회로를 덧붙여도 변하지 않는 소자 고유의 양이며, U = 1인 주파수가 f_max다.","chapters":["rf"]},
    {"ko":"최대 발진 주파수","en":"Maximum oscillation frequency","abbr":"f_max","def":"트랜지스터가 전력 이득을 낼 수 있는 가장 높은 주파수(U = 1). 대략 f_max ≈ √(f_T/(8πR_gC_gd))로, 게이트(베이스) 저항과 귀환 용량을 줄여야 높아진다.","chapters":["rf"]},
    {"ko":"게이트 저항","en":"Gate resistance","abbr":"R_g","def":"게이트 전극의 분포 저항과 콘택 저항, 채널의 비준정적 저항을 합한 값. 한쪽 접촉이면 띠 저항의 1/3, 양쪽 접촉이면 1/12이 되며 f_max와 잡음 지수를 직접 정한다.","chapters":["rf"]},
    {"ko":"다중 핑거 레이아웃","en":"Multi-finger layout","abbr":"","def":"넓은 트랜지스터를 폭 W_f의 게이트 핑거 n_f개로 나눠 소스·드레인을 공유하게 배치하는 방법. 게이트 저항이 약 1/n_f²로 줄고 드레인 접합 용량도 줄어든다.","chapters":["rf"]},
    {"ko":"디임베딩","en":"De-embedding","abbr":"","def":"측정한 S 파라미터에서 프로브 패드와 배선의 기생 성분을 빼 소자 자체의 특성을 얻는 절차. 같은 레이아웃의 개방·단락 더미를 함께 재서 뺀다.","chapters":["rf"]},
    {"ko":"열잡음","en":"Thermal noise","abbr":"","def":"저항 속 캐리어의 열운동에서 생기는 백색 잡음. 잡음 전압 밀도는 4kTR(V²/Hz)이며 상온 50 Ω에서 약 0.91 nV/√Hz다. 존슨–나이퀴스트 잡음이라고도 한다.","chapters":["rf"]},
    {"ko":"산탄 잡음","en":"Shot noise","abbr":"","def":"장벽을 넘는 전하가 하나하나 독립적으로 도착해 생기는 전류 요동. 잡음 전류 밀도는 2qI(A²/Hz)이며 다이오드와 BJT의 컬렉터·베이스 전류에서 나타난다.","chapters":["rf"]},
    {"ko":"1/f 잡음","en":"Flicker noise","abbr":"","def":"산화막 계면 근처 트랩의 포획·방출 등으로 스펙트럼이 주파수에 반비례하는 저주파 잡음. MOSFET의 입력 환산값은 약 K/(C_ox·WL·f)로 게이트 면적에 반비례한다.","chapters":["rf"]},
    {"ko":"1/f 코너 주파수","en":"Flicker corner frequency","abbr":"f_c","def":"1/f 잡음과 백색 잡음의 밀도가 같아지는 주파수. 짧은 채널 MOSFET은 수 MHz~수십 MHz, BJT·HBT는 수백 Hz~수 kHz이며, 발진기의 위상 잡음을 좌우한다.","chapters":["rf"]},
    {"ko":"과잉 잡음 계수","en":"Excess noise factor","abbr":"γ","def":"MOSFET 드레인 열잡음 4kTγg_d0의 계수. 긴 채널 포화 영역에서 2/3이고, 짧은 채널에서는 측정값이 약 1~2로 커진다.","chapters":["rf"]},
    {"ko":"유도 게이트 잡음","en":"Induced gate noise","abbr":"","def":"채널의 열잡음 요동이 게이트–채널 용량을 통해 게이트로 결합되어 생기는 잡음 전류. 크기는 ω²C_gs²에 비례하고 드레인 잡음과 부분적으로 상관(c ≈ 0.395j)되어 있다.","chapters":["rf"]},
    {"ko":"잡음 지수","en":"Noise figure","abbr":"NF","def":"입력 신호 대 잡음비와 출력 신호 대 잡음비의 비 F를 dB로 나타낸 값 NF = 10log F. 신호원 저항이 290 K에서 내는 잡음에 비해 증폭기가 잡음을 얼마나 더하는지를 뜻한다.","chapters":["rf"]},
    {"ko":"최소 잡음 지수","en":"Minimum noise figure","abbr":"NF_min","def":"신호원 어드미턴스를 최적값 Y_opt로 맞췄을 때(잡음 정합) 얻는 가장 낮은 잡음 지수. MOSFET에서는 F_min − 1이 대략 f/f_T에 비례한다.","chapters":["rf"]},
    {"ko":"잡음 파라미터","en":"Noise parameters","abbr":"","def":"2단자쌍의 잡음 지수를 신호원 어드미턴스의 함수 F = F_min + (R_n/G_s)|Y_s − Y_opt|²로 나타내는 네 값(F_min, R_n, Y_opt의 실수·허수부).","chapters":["rf"]},
    {"ko":"프리스 공식","en":"Friis formula","abbr":"","def":"여러 단을 직렬로 이은 시스템의 잡음 지수 F = F₁ + (F₂−1)/G₁ + (F₃−1)/(G₁G₂) + …. 첫 단의 이득이 크면 뒷단의 잡음이 작아지므로 첫 단이 감도를 정한다.","chapters":["rf"]},
    {"ko":"저잡음 증폭기","en":"Low-noise amplifier","abbr":"LNA","def":"수신기 안테나 바로 뒤에서 약한 신호를 잡음을 최소로 더하며 증폭하는 첫 단 증폭기. 입력 트랜지스터의 f_T, 게이트 저항, 폭이 잡음 지수를 결정한다.","chapters":["rf"]},
    {"ko":"존슨 한계","en":"Johnson limit","abbr":"","def":"트랜지스터의 속도와 항복 전압의 곱이 재료의 항복 전계와 포화 속도로 제한된다는 관계 f_T·BV ≲ E_br·v_sat/2π. Si는 약 0.5 THz·V, GaN은 약 13 THz·V다.","chapters":["rf"]},
    {"ko":"피크 f_T 전류 밀도","en":"Peak-fT current density","abbr":"","def":"f_T가 최대가 되는 드레인 전류를 게이트 폭으로 나눈 값. nMOS에서 공정 세대와 거의 무관하게 약 0.3 mA/µm이라, RF 설계는 V_GS 대신 전류 밀도로 바이어스를 정한다.","chapters":["rf"]},
    {"ko":"고장률","en":"Failure rate (hazard rate)","abbr":"h(t)","def":"지금까지 살아남은 소자가 다음 단위 시간 안에 고장 날 조건부 확률. h = f/R이며, 신뢰도는 R(t) = exp(−∫h dt)로 고장률에서 바로 구해진다.","chapters":["reliability"]},
    {"ko":"FIT","en":"Failures In Time","abbr":"FIT","def":"반도체 고장률 단위로, 10⁹ 소자·시간당 고장 1건. 100 FIT 칩 1만 개를 1년 쓰면 약 8.8개가 고장 난다.","chapters":["reliability"]},
    {"ko":"평균 고장 시간","en":"Mean Time To Failure","abbr":"MTTF","def":"신뢰도 함수를 시간에 대해 적분한 평균 수명. 고장률이 일정하면 1/λ지만, 마모 고장이 지배하는 실제 제품의 수명 내 누적 고장을 잘 나타내지 못한다.","chapters":["reliability"]},
    {"ko":"욕조 곡선","en":"Bathtub curve","abbr":"","def":"고장률을 시간에 대해 그린 곡선. 감소하는 초기 고장, 낮고 일정한 우발 고장, 다시 증가하는 마모 고장 구간이 욕조 모양을 이룬다.","chapters":["reliability"]},
    {"ko":"와이블 분포","en":"Weibull distribution","abbr":"","def":"F(t) = 1 − exp[−(t/η)^β]로 쓰는 고장 시간 분포. η는 63.2 %가 고장 나는 특성 수명, β는 형상 계수로 β < 1은 초기 고장, β > 1은 마모 고장을 뜻한다.","chapters":["reliability"]},
    {"ko":"번인","en":"Burn-in","abbr":"","def":"출하 전에 고온·고전압으로 제품을 일정 시간 동작시켜 초기 고장 소자를 미리 걸러내는 스크리닝. 현장 첫해 고장률을 크게 낮춘다.","chapters":["reliability"]},
    {"ko":"핫 캐리어 주입","en":"Hot-Carrier Injection","abbr":"HCI","def":"드레인 근처 고전계에서 큰 운동 에너지를 얻은 캐리어가 충돌 이온화를 일으키고 산화막·계면을 손상시켜 V_th 증가와 구동 전류 감소를 남기는 열화.","chapters":["reliability"]},
    {"ko":"행운 전자 모형","en":"Lucky-electron model","abbr":"","def":"전자가 에너지 φ를 얻으려면 거리 φ/qℰ를 충돌 없이 날아야 하므로 그 확률이 exp(−φ/qλℰ)라는 모형. 기판 전류와 게이트 주입 전류의 전계 의존성을 설명한다.","chapters":["reliability"]},
    {"ko":"기판 전류","en":"Substrate current","abbr":"I_sub","def":"충돌 이온화로 생긴 정공이 기판으로 흘러 생기는 전류. V_GS에 대해 종 모양이며 HCI 열화를 가늠하는 지표로 쓰인다.","chapters":["reliability"]},
    {"ko":"저농도 도핑 드레인","en":"Lightly Doped Drain","abbr":"LDD","def":"채널과 고농도 드레인 사이에 얕고 도핑이 낮은 영역을 두어 드레인 끝 최대 전계를 낮추는 구조. 핫 캐리어 열화를 크게 줄인다.","chapters":["reliability"]},
    {"ko":"음 바이어스 온도 불안정성","en":"Negative Bias Temperature Instability","abbr":"NBTI","def":"pMOS 게이트에 음전압을 걸고 고온에 두면 계면 트랩 생성과 산화막 정공 포획으로 |V_th|가 서서히 커지는 현상. 드레인 전류 없이도 진행된다.","chapters":["reliability"]},
    {"ko":"양 바이어스 온도 불안정성","en":"Positive Bias Temperature Instability","abbr":"PBTI","def":"high-k 게이트 nMOS에 양전압 스트레스를 주면 전자가 HfO₂ 속 결함에 포획되어 V_th가 커지는 현상.","chapters":["reliability"]},
    {"ko":"반응–확산 모형","en":"Reaction–Diffusion model","abbr":"R–D","def":"계면 Si–H 결합의 해리(반응)와 풀려난 수소의 산화막 확산으로 NBTI를 설명하는 모형. 확산이 율속 단계라 ΔV_th가 t^(1/6)~t^(1/4)로 증가한다.","chapters":["reliability"]},
    {"ko":"BTI 회복","en":"BTI recovery","abbr":"","def":"스트레스를 멈추면 포획된 전하가 방출되어 ΔV_th의 일부가 µs~수 년에 걸쳐 사라지는 현상. 측정 지연과 AC 듀티에 따라 측정되는 열화량이 달라진다.","chapters":["reliability"]},
    {"ko":"경시 절연 파괴","en":"Time-Dependent Dielectric Breakdown","abbr":"TDDB","def":"순간 파괴 전계보다 낮은 전계에서도 산화막 속 결함이 누적되어 결국 전도 경로가 생겨 파괴되는 현상.","chapters":["reliability"]},
    {"ko":"소프트 파괴 / 하드 파괴","en":"Soft / hard breakdown","abbr":"SBD/HBD","def":"얇은 산화막에서 처음 생긴 전도 경로가 누설 전류를 조금만 늘리는 소프트 파괴와, 경로가 열적으로 커져 저항성 단락이 되는 하드 파괴.","chapters":["reliability"]},
    {"ko":"퍼콜레이션 모형","en":"Percolation model","abbr":"","def":"산화막을 결함 크기 셀로 나누고 무작위로 생긴 결함이 게이트와 기판을 잇는 경로를 처음 완성할 때 파괴된다고 보는 모형. 와이블 기울기가 두께에 비례함을 설명한다.","chapters":["reliability"]},
    {"ko":"면적 스케일링","en":"Area scaling","abbr":"","def":"와이블 최약 고리 통계에서 면적이 A₂/A₁배이면 특성 수명이 (A₁/A₂)^(1/β)배가 되는 관계. β가 작을수록 큰 칩의 수명 벌점이 커진다.","chapters":["reliability"]},
    {"ko":"가속 계수","en":"Acceleration factor","abbr":"AF","def":"스트레스 조건의 수명 대비 사용 조건 수명의 비. 온도는 아레니우스 exp[(E_a/k)(1/T_use − 1/T_stress)], 전압은 지수 또는 멱 법칙으로 계산한다.","chapters":["reliability"]},
    {"ko":"고온 동작 수명 시험","en":"High-Temperature Operating Life","abbr":"HTOL","def":"제품을 고온(예: 125 °C)·최대 동작 전압에서 1,000 h 정도 동작시키는 대표적 신뢰성 시험. 고장 수와 카이제곱 분포로 FIT 상한을 구한다.","chapters":["reliability"]},
    {"ko":"정전기 방전","en":"Electrostatic Discharge","abbr":"ESD","def":"대전된 사람·장비·패키지에서 칩 핀으로 수 ns~수백 ns 동안 큰 전류가 흐르는 사건. 보호 소자 없이는 얇은 게이트 산화막이 즉시 파괴된다.","chapters":["reliability","esd"]},
    {"ko":"인체 모델 / 대전 소자 모델","en":"Human Body Model / Charged Device Model","abbr":"HBM/CDM","def":"ESD 시험 표준 모델. HBM은 100 pF를 1.5 kΩ으로 방전(감쇠 약 150 ns), CDM은 대전된 패키지가 한 핀으로 방전하는 폭 약 1 ns의 빠른 펄스다.","chapters":["reliability","esd"]},
    {"ko":"스냅백","en":"Snapback","abbr":"","def":"GGNMOS 같은 ESD 보호 소자가 트리거 전압에서 기생 바이폴라가 켜지며 낮은 유지 전압으로 떨어져 큰 전류를 흘리는 I–V 특성. 유지 전압이 V_DD보다 낮으면 래치업 위험이 있다.","chapters":["reliability","esd"]},
    {"ko":"전송선 펄스","en":"Transmission Line Pulse","abbr":"TLP","def":"충전한 동축 케이블을 방전해 폭 100 ns 안팎의 네모 펄스로 보호 소자의 준정적 I–V를 재는 방법. 펄스마다 DC 누설을 재서 파괴 전류 I_t2를 찾는다.","chapters":["esd"]},
    {"ko":"초고속 TLP","en":"very fast TLP","abbr":"vf-TLP","def":"펄스 폭 1~10 ns, 상승 100 ps 이하의 TLP. CDM 시간 규모에서 보호 소자의 켜짐 속도와 전압 오버슈트를 본다.","chapters":["esd"]},
    {"ko":"트리거 전압 / 유지 전압","en":"Trigger / holding voltage","abbr":"V_t1 / V_h","def":"스냅백 소자가 켜지는 전압과, 켜진 뒤 큰 전류를 흘리며 떨어진 낮은 전압. V_h가 V_DD보다 낮으면 래치업 위험이 있다.","chapters":["esd"]},
    {"ko":"2차 항복 전류","en":"Second breakdown current","abbr":"I_t2","def":"보호 소자가 국부 가열로 열 파괴되는 TLP 전류. HBM 내성은 대략 I_t2 × (1.5 kΩ + R_on)이다.","chapters":["esd"]},
    {"ko":"ESD 설계 창","en":"ESD design window","abbr":"","def":"보호 소자가 동작해야 하는 전압 범위. 정상 동작 전압(약 1.1 V_DD) 위에서 켜지고, 보호 대상 산화막·접합의 ns 파괴 전압 아래로 핀 전압을 묶어야 한다.","chapters":["esd"]},
    {"ko":"운쉬–벨 관계","en":"Wunsch–Bell relation","abbr":"","def":"ns~µs 펄스에서 접합의 열 파괴 전력이 펄스 폭의 제곱근에 반비례(P_f ∝ t^(−1/2))한다는 관계. 열 확산 거리가 √t로 줄기 때문이다.","chapters":["esd"]},
    {"ko":"GGNMOS","en":"Grounded-Gate NMOS","abbr":"GGNMOS","def":"게이트·소스·바디를 접지한 NMOS 보호 소자. 드레인 애벌런치 정공이 기판 저항에서 0.7 V를 만들면 기생 npn이 켜져 스냅백한다.","chapters":["esd"]},
    {"ko":"실리사이드 블록","en":"Silicide block (ballast)","abbr":"SAB","def":"드레인 일부에 실리사이드가 생기지 않게 막아 직렬 밸러스트 저항을 만드는 레이아웃. 멀티 핑거 보호 소자의 V_t2를 V_t1보다 높여 모든 핑거가 켜지게 한다.","chapters":["esd"]},
    {"ko":"레일 클램프","en":"Rail clamp (power clamp)","abbr":"","def":"전원과 접지 사이에 두어 ESD 전류를 받아내는 큰 소자. RC 트리거 클램프는 빠른 전압 상승을 RC로 감지해 큰 NMOS를 켜고, 느린 전원 켜짐에는 반응하지 않는다.","chapters":["esd"]},
    {"ko":"SCR 보호 소자","en":"Silicon-Controlled Rectifier","abbr":"SCR","def":"pnpn 사이리스터를 ESD 보호에 쓰는 소자. 유지 전압이 1~2 V로 낮아 면적 효율이 가장 좋지만 래치업과 느린 켜짐(CDM)에 주의해야 한다. LVTSCR은 NMOS로 트리거 전압을 낮춘 형태다.","chapters":["esd"]},
    {"ko":"가드 링","en":"Guard ring","abbr":"","def":"소자 둘레를 두른 고농도 확산 링. 주입된 소수 캐리어를 걷어 내 기생 트랜지스터의 β를 낮추고 탭 역할로 웰·기판 저항을 줄여 래치업을 막는다.","chapters":["esd"]},
    {"ko":"래치업 시험","en":"Latch-up test (JESD78)","abbr":"JESD78","def":"신호 핀에 ±100 mA를 주입하는 I 시험과 전원에 최대 전압의 1.5배를 거는 V 시험 뒤 전원 전류가 정상으로 돌아오는지 보는 JEDEC 규격. 등급 I은 상온, II는 최대 동작 온도.","chapters":["esd"]},
    {"ko":"시스템 수준 ESD","en":"System-level ESD (IEC 61000-4-2)","abbr":"","def":"완제품에 150 pF·330 Ω ESD 건으로 접촉 2~8 kV, 기중 최대 15 kV를 가하는 시험. 첫 정점이 3.75 A/kV라 보드의 TVS가 대부분을 받아야 한다.","chapters":["esd"]},
    {"ko":"TVS 다이오드","en":"Transient Voltage Suppressor","abbr":"TVS","def":"보드에서 커넥터 신호선을 접지로 묶어 시스템 수준 ESD 전류를 받는 부품. 칩 보호 소자와 병렬로 경쟁하므로 둘 사이 임피던스와 함께 설계한다.","chapters":["esd"]},
    {"ko":"SEED","en":"System-Efficient ESD Design","abbr":"SEED","def":"칩의 보호 소자와 보드의 TVS를 TLP 곡선과 직렬 임피던스로 함께 설계해 칩으로 가는 잔여 ESD 전류를 I_t2 아래로 묶는 방법.","chapters":["esd"]},
    {"ko":"2차 보호","en":"Secondary (local) protection","abbr":"","def":"보호 대상 게이트 바로 앞에 직렬 저항과 작은 클램프를 두어 게이트 전압을 국부적으로 묶는 구조. CDM 전원 영역 경계와 입력 버퍼에 쓴다.","chapters":["esd"]},
    {"ko":"자가 발열","en":"Self-heating","abbr":"","def":"소자가 소모하는 전력이 채널에서 열로 바뀌어 채널 온도가 주변보다 높아지는 현상. 열저항이 큰 FinFET·GAA에서 수십 K에 이르러 노화를 가속한다.","chapters":["reliability"]},
    {"ko":"가드밴드","en":"Guard band","abbr":"","def":"노화·변동성·온도 같은 불확실성을 덮기 위해 전압·주파수·온도 사양에 미리 남겨 두는 여유. 전력과 성능 손해를 대가로 수명 내 동작을 보장한다.","chapters":["reliability"]}
  ]
};
